        impl crate::agent::clean_authority_issuer::CleanManagementActorStore for IssuerMemoryStore {
            fn load_actor(&mut self) -> Result<Option<Vec<u8>>, MemoryError> {
                Ok(self.actor.lock().unwrap().clone())
            }
            fn commit_actor(&mut self, bytes: &[u8]) -> Result<(), MemoryError> {
                let failure = self.actor_failure.swap(0, Ordering::SeqCst);
                if failure == 1 {
                    return Err(MemoryError);
                }
                *self.actor.lock().unwrap() = Some(bytes.to_vec());
                if failure == 2 {
                    return Err(MemoryError);
                }
                Ok(())
            }
        }

        impl CleanManagementIssuerStore for IssuerMemoryStore {
            type Error = MemoryError;

            fn load(&mut self) -> Result<Option<Vec<u8>>, Self::Error> {
                Ok(self.image.lock().unwrap().clone())
            }

            fn commit(&mut self, image: &[u8]) -> Result<(), Self::Error> {
                if self.issuance_disabled()? && self.image.lock().unwrap().as_deref() != Some(image)
                {
                    return Err(MemoryError);
                }
                *self.image.lock().unwrap() = Some(image.to_vec());
                if (image.starts_with(b"CMR2") || image.starts_with(b"CND1"))
                    && self
                        .fail_retirement_after_commit
                        .as_ref()
                        .is_some_and(|fail| fail.swap(false, Ordering::SeqCst))
                {
                    return Err(MemoryError);
                }
                if let Some((clock, remaining)) = &mut self.advance_clock_after_commits {
                    if *remaining > 0 {
                        *remaining -= 1;
                        if *remaining == 0 {
                            clock.fetch_add(1, Ordering::AcqRel);
                        }
                    }
                }
                Ok(())
            }

            fn issuance_disabled(&mut self) -> Result<bool, Self::Error> {
                Ok(!self.is_management_continuation
                    && (self.management_image.lock().unwrap().is_some()
                        || self.management_handoff.lock().unwrap().is_some()))
            }
        }

        impl crate::agent::clean_authority_issuer::CleanSharedManagementIssuerStore for IssuerMemoryStore {
            fn load_management_handoff(&mut self) -> Result<Option<Vec<u8>>, MemoryError> {
                if self.is_management_continuation {
                    return Err(MemoryError);
                }
                Ok(self.management_handoff.lock().unwrap().clone())
            }

            fn commit_management_handoff(&mut self, marker: &[u8]) -> Result<(), MemoryError> {
                if self.is_management_continuation {
                    return Err(MemoryError);
                }
                let mut retained = self.management_handoff.lock().unwrap();
                if retained.as_ref().is_some_and(|saved| saved != marker) {
                    return Err(MemoryError);
                }
                *retained = Some(marker.to_vec());
                Ok(())
            }

            fn management_continuation(&mut self) -> Result<Self, MemoryError> {
                if self.is_management_continuation {
                    return Err(MemoryError);
                }
                Ok(Self {
                    image: self.management_image.clone(),
                    is_management_continuation: true,
                    ..self.clone()
                })
            }
        }

        struct CountingSigner {
            key: SigningKey,
            calls: usize,
            fail_receipt: bool,
            fail_denial: bool,
            fail_application: bool,
        }

        impl CountingSigner {
            fn new() -> Self {
                Self {
                    key: SigningKey::from_bytes(&[RECEIPT_SEED; 32]),
                    calls: 0,
                    fail_receipt: false,
                    fail_denial: false,
                    fail_application: false,
                }
            }
        }

        impl CleanManagementReceiptSigner for CountingSigner {
            type Error = MemoryError;

            fn sign_management_denial_retirement(
                &mut self,
                message: &[u8],
            ) -> Result<[u8; 64], Self::Error> {
                self.calls += 1;
                if core::mem::take(&mut self.fail_denial) {
                    return Err(MemoryError);
                }
                Ok(self.key.sign(message).to_bytes())
            }

            fn public_key(&self) -> [u8; 32] {
                self.key.verifying_key().to_bytes()
            }

            fn sign_authority_receipt(&mut self, message: &[u8]) -> Result<[u8; 64], Self::Error> {
                self.calls += 1;
                if core::mem::take(&mut self.fail_receipt) {
                    return Err(MemoryError);
                }
                Ok(self.key.sign(message).to_bytes())
            }

            fn sign_management_application_ack(
                &mut self,
                message: &[u8],
            ) -> Result<[u8; 64], Self::Error> {
                self.calls += 1;
                if core::mem::take(&mut self.fail_application) {
                    return Err(MemoryError);
                }
                Ok(self.key.sign(message).to_bytes())
            }
        }

        struct TestDirectory(PathBuf);

        impl TestDirectory {
            fn new(label: &str) -> Self {
                static NEXT: AtomicUsize = AtomicUsize::new(1);
                Self::claim(label, &NEXT)
            }

            fn claim(label: &str, next: &AtomicUsize) -> Self {
                // Separate PID namespaces can share TMPDIR and process IDs.
                // Claim a fresh directory atomically; never remove a path
                // that may belong to another live fixture or a previous run.
                loop {
                    let path = std::env::temp_dir().join(format!(
                        "vos-clean-system-bootstrap-{label}-{}-{}",
                        std::process::id(),
                        next.fetch_add(1, Ordering::Relaxed),
                    ));
                    match std::fs::create_dir(&path) {
                        Ok(()) => return Self(path),
                        Err(error) if error.kind() == std::io::ErrorKind::AlreadyExists => continue,
                        Err(error) => panic!("cannot create bootstrap fixture: {error}"),
                    }
                }
            }

            fn host(&self) -> PathBuf {
                self.0.join("agents")
            }

            fn lock(&self) -> PathBuf {
                self.0.join("shared-host.lock")
            }
        }

        impl Drop for TestDirectory {
            fn drop(&mut self) {
                let _ = std::fs::remove_dir_all(&self.0);
            }
        }

        #[test]
        fn bootstrap_test_directories_preserve_existing_candidates() {
            // Independent counters model two processes with the same PID in
            // separate namespaces sharing one temporary directory.
            let first = TestDirectory::claim("directory-collision", &AtomicUsize::new(1));
            let second = TestDirectory::claim("directory-collision", &AtomicUsize::new(1));
            assert_ne!(first.0, second.0);
            drop(second);
            assert!(first.0.is_dir());
        }

