        struct SigningMerge {
            key: SigningKey,
            node: HostNodeId,
        }

        impl LocalMergeAuthenticator for SigningMerge {
            fn node(&self) -> HostNodeId {
                self.node
            }

            fn sign_event(&self, event: &mut MergeEvent) -> bool {
                if event.author != self.node || !event.signature.is_empty() {
                    return false;
                }
                event.signature = self
                    .key
                    .sign(&event.signing_message().0)
                    .to_bytes()
                    .to_vec();
                true
            }

            fn verify_event(&self, event: &MergeEvent) -> bool {
                event.author == self.node && event.signature.len() == ED25519_SIGNATURE_BYTES
            }

            fn sign_snapshot_candidate(
                &self,
                candidate: &crate::agent::shared_host::VerifiedSharedAgentSnapshotCandidate,
            ) -> Option<crate::agent::shared_commit::ReplicaCommitSignature> {
                let member = candidate
                    .claim()
                    .active_committee()
                    .member_by_node(self.node)?;
                let keypair =
                    libp2p::identity::Keypair::ed25519_from_bytes(self.key.to_bytes()).ok()?;
                let peer = keypair.public().to_peer_id().to_bytes();
                if member.replica().role != HostReplicaRole::Voter
                    || member.ed25519_public_key() != &self.key.verifying_key().to_bytes()
                    || member.peer_id() != peer
                {
                    return None;
                }
                crate::agent::shared_commit::ReplicaCommitSignature::new(
                    self.node,
                    self.key.sign(&candidate.signing_message().0).to_bytes(),
                )
                .ok()
            }

            fn sign_common_snapshot_candidate(
                &self,
                candidate: &crate::agent::shared_host::VerifiedSharedAgentCommonSnapshotCandidate,
            ) -> Option<crate::agent::shared_commit::ReplicaCommitSignature> {
                crate::agent::local_journal_driver::Ed25519NodeMergeAuthenticator::new(
                    libp2p::identity::Keypair::ed25519_from_bytes(self.key.to_bytes()).ok()?,
                )
                .ok()?
                .sign_common_snapshot_candidate(candidate)
            }

            fn sign_recovery_expiry_candidate(
                &self,
                candidate: &crate::agent::shared_host::VerifiedSharedRecoveryExpiryCandidate,
            ) -> Option<crate::agent::shared_commit::ReplicaCommitSignature> {
                crate::agent::local_journal_driver::Ed25519NodeMergeAuthenticator::new(
                    libp2p::identity::Keypair::ed25519_from_bytes(self.key.to_bytes()).ok()?,
                )
                .ok()?
                .sign_recovery_expiry_candidate(candidate)
            }

            fn sign_local_snapshot_candidate(
                &self,
                candidate: &crate::agent::shared_host::VerifiedSharedAgentLocalSnapshotCandidate,
            ) -> Option<crate::agent::shared_commit::ReplicaCommitSignature> {
                crate::agent::local_journal_driver::Ed25519NodeMergeAuthenticator::new(
                    libp2p::identity::Keypair::ed25519_from_bytes(self.key.to_bytes()).ok()?,
                )
                .ok()?
                .sign_local_snapshot_candidate(candidate)
            }

            fn sign_projection_recovery_registration(
                &self,
                candidate: &VerifiedProjectionRecoveryRegistration,
            ) -> Option<crate::agent::shared_commit::ReplicaCommitSignature> {
                crate::agent::local_journal_driver::Ed25519NodeMergeAuthenticator::new(
                    libp2p::identity::Keypair::ed25519_from_bytes(self.key.to_bytes()).ok()?,
                )
                .ok()?
                .sign_projection_recovery_registration(candidate)
            }
        }

