        #[test]
        fn native_shared_genesis_controller_refuses_an_unadmitted_handoff() {
            let mut harness = NativeProjectionOwnerHarness::new("shared-unadmitted-handoff");
            let owner = harness.owner.as_mut().unwrap();
            let authority = owner.authority_target();
            let locator = crate::agent::genesis::AgentGenesisLocator {
                space: HostSpaceId(authority.space.0),
                agent: HostAgentId([0xe9; 32]),
            };
            let before = owner.ordered_index_for_test().unwrap();
            for marker in [false, true] {
                let source = IssuerMemoryStore::default();
                let retained = if marker {
                    &source.management_handoff
                } else {
                    &source.management_image
                };
                *retained.lock().unwrap() = Some(vec![0x91]);
                assert!(matches!(
                    NativeSharedGenesisRecovery::open(
                        authority,
                        locator,
                        IssuerMemoryStore::default(),
                        source.clone(),
                        IssuerMemoryStore::default(),
                        IssuerMemoryStore::default(),
                        IssuerMemoryStore::default(),
                        IssuerMemoryStore::default(),
                    ),
                    Err(SharedAgentHostError::Conflict)
                ));
                // Explicit handoff recovery still requires the signed original
                // Create; a sidecar alone cannot manufacture an admitted owner.
                assert!(matches!(
                    NativeSharedGenesisRecovery::open_with_management_handoff(
                        authority,
                        locator,
                        IssuerMemoryStore::default(),
                        source.clone(),
                        IssuerMemoryStore::default(),
                        IssuerMemoryStore::default(),
                        IssuerMemoryStore::default(),
                        IssuerMemoryStore::default(),
                    ),
                    Err(SharedAgentHostError::ScopeMismatch)
                ));
                assert_eq!(*retained.lock().unwrap(), Some(vec![0x91]));
                assert!(source.image.lock().unwrap().is_none());
            }
            assert_eq!(owner.ordered_index_for_test().unwrap(), before);
            harness.stop();
        }

        #[test]
        fn native_shared_genesis_controller_preserves_incomplete_archive_ownership() {
            struct Archive {
                image: Option<Vec<u8>>,
                lifetime: Arc<()>,
            }
            impl crate::agent::genesis_archive::AgentGenesisArchiveStore for Archive {
                type Error = ();
                fn load(
                    &self,
                    _: crate::agent::genesis::AgentGenesisLocator,
                ) -> Result<Option<Vec<u8>>, ()> {
                    let _ = &self.lifetime;
                    Ok(self.image.clone())
                }
                fn insert_if_absent(
                    &self,
                    _: crate::agent::genesis::AgentGenesisLocator,
                    _: &[u8],
                ) -> Result<(), ()> {
                    panic!("recovery must not create an archive");
                }
            }
            let mut harness = NativeProjectionOwnerHarness::new("shared-controller-incomplete");
            let owner = harness.owner.as_mut().unwrap();
            let runtime = shape_only_runtime();
            let mut descriptor = owner.pins.descriptor.clone();
            descriptor.creation_nonce = Hash([0xdd; 32]);
            descriptor.identity.agent = AgentId::derive(
                descriptor.identity.space,
                descriptor.identity.owner,
                descriptor.creation_nonce.as_bytes(),
            );
            descriptor.identity.runtime_deployment = runtime.deployment();
            descriptor.identity.runtime_program = runtime.program();
            descriptor.identity.runtime_producer = runtime.producer();
            descriptor.runtime_package = runtime.package_ref().clone();
            descriptor.runtime_contract = runtime.manifest().contract;
            descriptor.capabilities = runtime.capabilities();
            descriptor.replicas[0].principal = descriptor.identity.owner;
            let request = ManagementRequest::Create(Box::new(descriptor.clone()));
            let key = SigningKey::from_bytes(&[CREDENTIAL_SEED; 32]);
            let (mut call, _) = credential_call_and_approval(&descriptor, &request, &key);
            call.authority = owner.authority_target();
            call.invocation = call.expected_invocation();
            call.signature = key.sign(&call.signing_bytes()).to_bytes();
            let locator = crate::agent::genesis::AgentGenesisLocator {
                space: crate::service::SpaceId(descriptor.identity.space.0),
                agent: HostAgentId(descriptor.identity.agent.0),
            };
            let before = owner.ordered_index_for_test().unwrap();
            for mode in 0..3 {
                let intent = IssuerMemoryStore::default();
                let recovery = NativeSharedGenesisRecovery::reserve_create(
                    owner.authority_target(),
                    locator,
                    descriptor.clone(),
                    call.clone(),
                    runtime.clone(),
                    (
                        intent.clone(),
                        IssuerMemoryStore::default(),
                        IssuerMemoryStore::default(),
                        IssuerMemoryStore::default(),
                        IssuerMemoryStore::default(),
                        IssuerMemoryStore::default(),
                    ),
                )
                .unwrap();
                let before_intent = intent.image.lock().unwrap().clone();
                let lifetime = Arc::new(());
                let weak = Arc::downgrade(&lifetime);
                let archive = if mode == 0 {
                    None
                } else {
                    Some(Archive {
                        image: (mode == 2).then(|| vec![0xff]),
                        lifetime: lifetime.clone(),
                    })
                };
                drop(lifetime);
                let mut controller = NativeSharedGenesisController::new(
                    owner.authority_target(),
                    vec![(recovery, archive)],
                )
                .unwrap();
                let mut signer = CountingSigner::new();
                for _ in 0..2 {
                    assert_eq!(
                        controller.recover(owner, &mut signer),
                        Err(if mode == 2 {
                            SharedAgentHostError::ScopeMismatch
                        } else {
                            SharedAgentHostError::Unavailable
                        })
                    );
                    assert!(!controller.is_recovered());
                    assert_eq!(owner.ordered_index_for_test().unwrap(), before);
                    assert_eq!(*intent.image.lock().unwrap(), before_intent);
                    assert_eq!(signer.calls, 0);
                    assert_eq!(weak.upgrade().is_some(), mode != 0);
                }
                drop(controller);
                assert!(weak.upgrade().is_none());
            }
            harness.stop();
        }

        fn check_native_shared_unissued_create_restarts(endorse: bool) {
            use crate::agent::genesis::AgentReplicaMember;

            struct NoArchive(bool);
            impl crate::agent::genesis_archive::AgentGenesisArchiveStore for NoArchive {
                type Error = ();
                fn load(
                    &self,
                    _: crate::agent::genesis::AgentGenesisLocator,
                ) -> Result<Option<Vec<u8>>, ()> {
                    if self.0 {
                        Ok(None)
                    } else {
                        panic!("an unissued Create has no archive lease")
                    }
                }
                fn insert_if_absent(
                    &self,
                    _: crate::agent::genesis::AgentGenesisLocator,
                    _: &[u8],
                ) -> Result<(), ()> {
                    panic!("startup cannot publish an archive")
                }
            }

            let mut harness = if endorse {
                NativeProjectionOwnerHarness::with_real_bootstrap(
                    "shared-unissued-endorsement",
                    native_bundled_authority_fixture(),
                )
            } else {
                NativeProjectionOwnerHarness::new("shared-unissued-restart")
            };
            let owner = harness.owner.take().unwrap();
            let target = owner.authority_target();
            let before = owner.ordered_index_for_test().unwrap();
            let runtime = test_runtime_package(endorse);
            let mut descriptor = owner.pins.descriptor.clone();
            descriptor.creation_nonce = Hash([0xd3; 32]);
            descriptor.identity.agent = AgentId::derive(
                descriptor.identity.space,
                descriptor.identity.owner,
                descriptor.creation_nonce.as_bytes(),
            );
            descriptor.identity.runtime_deployment = runtime.deployment();
            descriptor.identity.runtime_program = runtime.program();
            descriptor.identity.runtime_producer = runtime.producer();
            descriptor.runtime_package = runtime.package_ref().clone();
            descriptor.runtime_contract = runtime.manifest().contract;
            descriptor.capabilities = runtime.capabilities();
            descriptor.replicas[0].principal = descriptor.identity.owner;
            let original = &owner.pins.replicas.members()[0];
            let mut replica = original.replica();
            replica.principal = crate::service::PrincipalId(descriptor.identity.owner.0);
            let member = AgentReplicaMember::new(
                replica,
                original.peer_id().to_vec(),
                *original.ed25519_public_key(),
                original.raft_slot(),
            )
            .unwrap();
            let replicas = AgentReplicaCommittee::new(
                crate::service::SpaceId(descriptor.identity.space.0),
                HostAgentId(descriptor.identity.agent.0),
                crate::agent::AgentProfile::Shared,
                vec![member],
            )
            .unwrap();
            replicas.validate_for_clean_descriptor(&descriptor).unwrap();
            let request = ManagementRequest::Create(Box::new(descriptor.clone()));
            let key = SigningKey::from_bytes(&[CREDENTIAL_SEED; 32]);
            let (mut call, _) = credential_call_and_approval(&descriptor, &request, &key);
            if endorse {
                // Real bootstrap already consumed sequence one for Catalog.
                call.request_sequence = NonZeroU64::new(2).unwrap();
            }
            call.authority = target;
            call.invocation = call.expected_invocation();
            call.signature = key.sign(&call.signing_bytes()).to_bytes();
            let locator = crate::agent::genesis::AgentGenesisLocator {
                space: crate::service::SpaceId(descriptor.identity.space.0),
                agent: HostAgentId(descriptor.identity.agent.0),
            };
            let intent_store = IssuerMemoryStore::default();
            let retained_stores = (
                intent_store.clone(),
                IssuerMemoryStore::default(),
                IssuerMemoryStore::default(),
                IssuerMemoryStore::default(),
                IssuerMemoryStore::default(),
                IssuerMemoryStore::default(),
            );
            let recovery = NativeSharedGenesisRecovery::reserve_create_with_replicas(
                target,
                locator,
                descriptor,
                call,
                runtime,
                replicas,
                retained_stores.clone(),
            )
            .unwrap();
            let retained_intent = intent_store.image.lock().unwrap().clone();
            let mut controller = NativeSharedGenesisController::new(
                target,
                vec![(recovery, endorse.then_some(NoArchive(true)))],
            )
            .unwrap();
            let pins = owner._pins_store.clone();
            let record = owner.record_store.clone();
            let issuer = owner.issuer.into_store();
            drop(owner._network_host);
            drop(owner.host);
            let mut operations = OperationTestJournal(harness._directory.0.clone());
            let admission =
                NativeAuthorityOperationStartupAdmission::load(&mut operations, target, &[])
                    .unwrap();
            let admission = controller.startup_admission(admission).unwrap();
            let mut owner =
                CleanSystemAgentBootstrapOwner::open_or_bootstrap_with_operation_admission(
                    pins,
                    record,
                    issuer,
                    &mut CountingSigner::new(),
                    || panic!("restart must not recreate bootstrap"),
                    harness._directory.host(),
                    harness._directory.lock(),
                    harness.fixture.plan.pins.space,
                    harness.fixture.plan.pins.node,
                    harness.fixture.trust.clone(),
                    harness.fixture.merge.clone(),
                    harness.fixture.finality.clone(),
                    harness.provider.clone(),
                    harness.network.clone(),
                    None,
                    Some(&admission),
                )
                .unwrap();
            drop(admission);
            assert!(owner.host.lock().unwrap().has_deferred_open());
            assert!(owner.host.lock().unwrap().deferred_agent_ids().is_empty());
            let mut signer = CountingSigner::new();
            controller.recover(&mut owner, &mut signer).unwrap();
            assert!(controller.is_recovered());
            assert!(!owner.host.lock().unwrap().has_deferred_open());
            assert_eq!(owner.host.lock().unwrap().len(), 1);
            assert!(owner.ordinary_supervisor_generations().unwrap().is_empty());
            assert_eq!(owner.ordered_index_for_test().unwrap(), before);
            assert_eq!(*intent_store.image.lock().unwrap(), retained_intent);
            assert_eq!(signer.calls, 0);
            if endorse {
                struct GenesisSigner(SigningKey);
                impl super::super::genesis_issuance::GenesisClaimSigner for GenesisSigner {
                    type Error = ();
                    fn public_key(&self) -> [u8; 32] {
                        self.0.verifying_key().to_bytes()
                    }
                    fn sign_genesis_claim(&mut self, message: &[u8; 32]) -> Result<[u8; 64], ()> {
                        Ok(self.0.sign(message).to_bytes())
                    }
                }
                let mut genesis_signer =
                    GenesisSigner(SigningKey::from_bytes(&[CREDENTIAL_SEED; 32]));
                let mut signature_store = IssuerMemoryStore::default();
                let (candidate, committee, signature) = controller
                    .endorse_pending_create(
                        &mut owner,
                        locator,
                        &mut signer,
                        &mut signature_store,
                        &mut genesis_signer,
                    )
                    .unwrap();
                assert_eq!(candidate.proposal().locator(), locator);
                assert_eq!(committee.members().len(), 1);
                assert_eq!(signature.signer(), committee.members()[0].signer());
                let endorsed_index = owner.ordered_index_for_test().unwrap();
                let expected_endorsement =
                    (candidate.clone(), committee.clone(), signature.clone());
                let receipt_signatures = signer.calls;
                let retained_signature = signature_store.image.lock().unwrap().clone();
                let (retried, retried_committee, retried_signature) = controller
                    .endorse_pending_create(
                        &mut owner,
                        locator,
                        &mut signer,
                        &mut signature_store,
                        &mut genesis_signer,
                    )
                    .unwrap();
                assert_eq!(
                    (retried, retried_committee, retried_signature),
                    (candidate, committee, signature)
                );
                assert_eq!(owner.ordered_index_for_test().unwrap(), endorsed_index);
                assert_eq!(signer.calls, receipt_signatures);
                assert_eq!(*signature_store.image.lock().unwrap(), retained_signature);
                assert!(owner.ordinary_supervisor_generations().unwrap().is_empty());
                assert_eq!(owner.host.lock().unwrap().len(), 1);
                // Lose every lifecycle and system owner after endorsement,
                // while no archive or ordinary generation exists yet.
                drop(controller);
                let pins = owner._pins_store;
                let record = owner.record_store;
                let issuer = owner.issuer.into_store();
                drop(owner._network_host);
                drop(owner.host);
                let (intent, issued, query, reply, publication, publication_reply) =
                    retained_stores;
                let recovery = NativeSharedGenesisRecovery::open(
                    target,
                    locator,
                    intent,
                    issued,
                    query,
                    reply,
                    publication,
                    publication_reply,
                )
                .unwrap();
                assert_eq!(recovery.pending.len(), 2);
                assert!(recovery.issued.is_some());
                controller = NativeSharedGenesisController::new(
                    target,
                    vec![(recovery, Some(NoArchive(true)))],
                )
                .unwrap();
                let admission =
                    NativeAuthorityOperationStartupAdmission::load(&mut operations, target, &[])
                        .unwrap();
                let admission = controller.startup_admission(admission).unwrap();
                owner = CleanSystemAgentBootstrapOwner::open_or_bootstrap_with_operation_admission(
                    pins,
                    record,
                    issuer,
                    &mut signer,
                    || panic!("endorsed restart cannot recreate bootstrap"),
                    harness._directory.host(),
                    harness._directory.lock(),
                    harness.fixture.plan.pins.space,
                    harness.fixture.plan.pins.node,
                    harness.fixture.trust.clone(),
                    harness.fixture.merge.clone(),
                    harness.fixture.finality.clone(),
                    harness.provider.clone(),
                    harness.network.clone(),
                    None,
                    Some(&admission),
                )
                .unwrap();
                drop(admission);
                controller.recover(&mut owner, &mut signer).unwrap();
                assert!(controller.is_recovered());
                assert_eq!(owner.ordered_index_for_test().unwrap(), endorsed_index);
                assert_eq!(signer.calls, receipt_signatures);
                assert!(owner.management_admission_held().unwrap());
                assert_eq!(
                    controller
                        .endorse_pending_create(
                            &mut owner,
                            locator,
                            &mut signer,
                            &mut signature_store,
                            &mut genesis_signer,
                        )
                        .unwrap(),
                    expected_endorsement,
                );
                assert_eq!(owner.ordered_index_for_test().unwrap(), endorsed_index);
                assert_eq!(*signature_store.image.lock().unwrap(), retained_signature);
                assert!(owner.ordinary_supervisor_generations().unwrap().is_empty());
                assert_eq!(owner.host.lock().unwrap().len(), 1);
            }
            drop(controller);
            drop(owner);
            harness.stop();
        }

        #[test]
        fn native_shared_unissued_create_restarts_without_exposing_a_route() {
            check_native_shared_unissued_create_restarts(false);
        }

        #[test]
        #[ignore = "requires the bundled outer PVM; run with VOS_AGENT_PROFILE_REFINE_MACHINES=1"]
        fn native_shared_unissued_create_endorses_after_restart_without_route() {
            check_native_shared_unissued_create_restarts(true);
        }

        fn check_shared_system_bootstrap(use_controller: u8) {
            struct NoArchive(bool);
            impl crate::agent::genesis_archive::AgentGenesisArchiveStore for NoArchive {
                type Error = ();
                fn load(
                    &self,
                    _: crate::agent::genesis::AgentGenesisLocator,
                ) -> Result<Option<Vec<u8>>, ()> {
                    assert!(self.0, "empty recovery must not read an archive");
                    Ok(None)
                }
                fn insert_if_absent(
                    &self,
                    _: crate::agent::genesis::AgentGenesisLocator,
                    _: &[u8],
                ) -> Result<(), ()> {
                    panic!("recovery must not publish an archive");
                }
            }
            let mut harness = NativeProjectionOwnerHarness::new("deferred-system-bootstrap");
            let owner = harness.owner.take().unwrap();
            let target = owner.authority_target();
            let mut controller = NativeSharedGenesisController::<
                IssuerMemoryStore,
                IssuerMemoryStore,
                IssuerMemoryStore,
                IssuerMemoryStore,
                IssuerMemoryStore,
                IssuerMemoryStore,
                NoArchive,
            >::new(target, Vec::new())
            .unwrap();
            let before = owner.ordered_index_for_test().unwrap();
            let pins = owner._pins_store.clone();
            let record = owner.record_store.clone();
            let issuer = owner.issuer.into_store();
            drop(owner._network_host);
            drop(owner.host);
            let mut operations = OperationTestJournal(harness._directory.0.clone());
            let admission =
                NativeAuthorityOperationStartupAdmission::load(&mut operations, target, &[])
                    .unwrap();
            let admission = if use_controller != 0 {
                controller.startup_admission(admission).unwrap()
            } else {
                admission.with_deferred_shared_genesis()
            };
            let mut owner =
                CleanSystemAgentBootstrapOwner::open_or_bootstrap_with_operation_admission(
                    pins,
                    record,
                    issuer,
                    &mut CountingSigner::new(),
                    || panic!("staged recovery must not recreate bootstrap"),
                    harness._directory.host(),
                    harness._directory.lock(),
                    harness.fixture.plan.pins.space,
                    harness.fixture.plan.pins.node,
                    harness.fixture.trust.clone(),
                    harness.fixture.merge.clone(),
                    harness.fixture.finality.clone(),
                    harness.provider.clone(),
                    harness.network.clone(),
                    None,
                    Some(&admission),
                )
                .unwrap();
            drop(admission);
            assert_eq!(owner.authority_target(), target);
            assert_eq!(owner.ordered_index_for_test().unwrap(), before);
            assert_eq!(owner.host.lock().unwrap().len(), 1);
            assert!(owner.host.lock().unwrap().deferred_agent_ids().is_empty());
            assert_eq!(
                owner.host.lock().unwrap().has_deferred_open(),
                use_controller == 0,
                "an empty controller must not force deferred opening"
            );
            if use_controller >= 2 {
                struct NoLocalStores;
                impl crate::agent::local_lifecycle::LocalLifecycleStoreFactory for NoLocalStores {
                    type Intent = IssuerMemoryStore;
                    type Issuer = IssuerMemoryStore;
                    type Error = ();
                    fn discover(&mut self, _: SpaceId, _: usize) -> Result<Vec<AgentId>, ()> {
                        Ok(Vec::new())
                    }
                    fn open_existing(
                        &mut self,
                        _: SpaceId,
                        _: AgentId,
                    ) -> Result<(Self::Intent, Self::Issuer), ()> {
                        Err(())
                    }
                    fn open(
                        &mut self,
                        _: SpaceId,
                        _: AgentId,
                    ) -> Result<(Self::Intent, Self::Issuer), ()> {
                        Err(())
                    }
                }
                let host = Arc::downgrade(&owner.host);
                let local = crate::agent::local_sdk_host::LocalAgentHost::create(
                    harness._directory.0.join("local"),
                    owner.pins.space,
                    owner.pins.node,
                    harness.fixture.trust.clone(),
                )
                .unwrap();
                let lifecycle = crate::agent::local_lifecycle::LocalLifecycleController::new(
                    owner,
                    local,
                    NoLocalStores,
                    CountingSigner::new(),
                )
                .unwrap();
                let lifecycle = if use_controller == 2 {
                    lifecycle.with_shared_genesis(controller).unwrap()
                } else {
                    let runtime = shape_only_runtime();
                    let mut descriptor = lifecycle.system_for_test().pins.descriptor.clone();
                    descriptor.creation_nonce = Hash([0xde; 32]);
                    descriptor.identity.agent = AgentId::derive(
                        descriptor.identity.space,
                        descriptor.identity.owner,
                        descriptor.creation_nonce.as_bytes(),
                    );
                    descriptor.identity.runtime_deployment = runtime.deployment();
                    descriptor.identity.runtime_program = runtime.program();
                    descriptor.identity.runtime_producer = runtime.producer();
                    descriptor.runtime_package = runtime.package_ref().clone();
                    descriptor.runtime_contract = runtime.manifest().contract;
                    descriptor.capabilities = runtime.capabilities();
                    descriptor.replicas[0].principal = descriptor.identity.owner;
                    let original = lifecycle.system_for_test().pins.replicas.members()[0].clone();
                    let mut replica = original.replica();
                    replica.principal = crate::service::PrincipalId(descriptor.identity.owner.0);
                    let replicas = AgentReplicaCommittee::new(
                        crate::service::SpaceId(descriptor.identity.space.0),
                        HostAgentId(descriptor.identity.agent.0),
                        crate::agent::AgentProfile::Shared,
                        vec![
                            crate::agent::genesis::AgentReplicaMember::new(
                                replica,
                                original.peer_id().to_vec(),
                                *original.ed25519_public_key(),
                                original.raft_slot(),
                            )
                            .unwrap(),
                        ],
                    )
                    .unwrap();
                    let key = SigningKey::from_bytes(&[CREDENTIAL_SEED; 32]);
                    let request = ManagementRequest::Create(Box::new(descriptor.clone()));
                    let (mut call, _) = credential_call_and_approval(&descriptor, &request, &key);
                    call.authority = target;
                    call.invocation = call.expected_invocation();
                    call.signature = key.sign(&call.signing_bytes()).to_bytes();
                    assert_eq!(
                        controller.reserve_create_with(
                            &descriptor,
                            &call,
                            &runtime,
                            &replicas,
                            || panic!("startup must finish before reservation allocation")
                        ),
                        Err(SharedAgentHostError::Conflict)
                    );
                    let allocations = Arc::new(AtomicUsize::new(0));
                    let allocated = allocations.clone();
                    let mut lifecycle = lifecycle
                        .with_shared_genesis_admission(
                            controller,
                            move |descriptor, call, runtime, replicas| {
                                allocated.fetch_add(1, Ordering::Relaxed);
                                let locator = crate::agent::genesis::AgentGenesisLocator {
                                    space: crate::service::SpaceId(descriptor.identity.space.0),
                                    agent: HostAgentId(descriptor.identity.agent.0),
                                };
                                let recovery =
                                    NativeSharedGenesisRecovery::reserve_create_with_replicas(
                                        target,
                                        locator,
                                        descriptor.clone(),
                                        call.clone(),
                                        runtime.clone(),
                                        replicas.clone(),
                                        (
                                            IssuerMemoryStore::default(),
                                            IssuerMemoryStore::default(),
                                            IssuerMemoryStore::default(),
                                            IssuerMemoryStore::default(),
                                            IssuerMemoryStore::default(),
                                            IssuerMemoryStore::default(),
                                        ),
                                    )?;
                                Ok((recovery, Some(NoArchive(true))))
                            },
                        )
                        .unwrap();
                    let locator = lifecycle
                        .reserve_shared_create(&descriptor, &call, &runtime, &replicas)
                        .unwrap();
                    assert_eq!(locator.agent.0, descriptor.identity.agent.0);
                    assert_eq!(
                        lifecycle.reserve_shared_create(&descriptor, &call, &runtime, &replicas),
                        Ok(locator)
                    );
                    assert_eq!(allocations.load(Ordering::Relaxed), 1);
                    let mut replacement = call.clone();
                    replacement.request_sequence =
                        NonZeroU64::new(call.request_sequence.get() + 1).unwrap();
                    replacement.invocation = replacement.expected_invocation();
                    replacement.signature = key.sign(&replacement.signing_bytes()).to_bytes();
                    assert_eq!(
                        lifecycle.reserve_shared_create(
                            &descriptor,
                            &replacement,
                            &runtime,
                            &replicas
                        ),
                        Err(SharedAgentHostError::Conflict)
                    );
                    assert_eq!(allocations.load(Ordering::Relaxed), 1);
                    assert!(
                        lifecycle
                            .system_for_test()
                            .ordinary_supervisor_generations()
                            .unwrap()
                            .is_empty()
                    );
                    assert!(
                        !lifecycle
                            .system_for_test()
                            .management_admission_held()
                            .unwrap()
                    );
                    lifecycle
                };
                assert!(!host.upgrade().unwrap().lock().unwrap().has_deferred_open());
                assert_eq!(lifecycle.ordered_index_for_test().unwrap(), before);
                drop(lifecycle);
                assert!(
                    host.upgrade().is_none(),
                    "lifecycle drop must release the physical host"
                );
                harness.stop();
                return;
            }
            let mut entries: Vec<(
                &mut NativeSharedGenesisRecovery<
                    IssuerMemoryStore,
                    IssuerMemoryStore,
                    IssuerMemoryStore,
                    IssuerMemoryStore,
                    IssuerMemoryStore,
                    IssuerMemoryStore,
                >,
                &crate::agent::genesis::AgentGenesisArchiveRecord,
            )> = Vec::new();
            if use_controller != 0 {
                assert!(!controller.is_recovered());
                controller
                    .recover(&mut owner, &mut CountingSigner::new())
                    .unwrap();
                assert!(controller.is_recovered());
                assert_eq!(
                    controller.recover(&mut owner, &mut CountingSigner::new()),
                    Err(SharedAgentHostError::Conflict)
                );
                let admission =
                    NativeAuthorityOperationStartupAdmission::load(&mut operations, target, &[])
                        .unwrap();
                assert!(matches!(
                    controller.startup_admission(admission),
                    Err(SharedAgentHostError::Conflict)
                ));
            } else {
                owner
                    .recover_deferred_shared_generations(&mut entries, &mut CountingSigner::new())
                    .unwrap();
            }
            assert_eq!(
                owner.recover_deferred_shared_generations(&mut entries, &mut CountingSigner::new()),
                Err(SharedAgentHostError::Conflict)
            );
            assert_eq!(
                owner.complete_deferred_shared_genesis(Vec::new()),
                Err(SharedAgentHostError::Conflict)
            );
            assert_eq!(owner.ordered_index_for_test().unwrap(), before);
            harness.owner = Some(owner);
            harness.stop();
        }

        #[test]
        fn native_shared_system_owner_survives_route_retirement_and_fails_closed_on_poison() {
            let mut harness = NativeProjectionOwnerHarness::new("shared-system-owner");
            let owner = Arc::new(Mutex::new(harness.owner.take().unwrap()));
            let expected = owner.lock().unwrap().authority_target();
            let attachment =
                crate::agent::supervisor_adapters::system_agent_supervisor_attachment_shared(
                    owner.clone(),
                    4,
                )
                .unwrap();
            assert_eq!(attachment.handle().authority_target().unwrap(), expected);
            let guard = owner.lock().unwrap();
            let handle = attachment.handle();
            let (sent, received) = std::sync::mpsc::channel();
            let thread = std::thread::spawn(move || sent.send(handle.authority_target()).unwrap());
            assert!(matches!(
                received.recv_timeout(std::time::Duration::from_millis(20)),
                Err(std::sync::mpsc::RecvTimeoutError::Timeout)
            ));
            drop(guard);
            assert_eq!(
                received
                    .recv_timeout(std::time::Duration::from_secs(5))
                    .unwrap()
                    .unwrap(),
                expected
            );
            thread.join().unwrap();
            attachment.retire().unwrap();
            assert_eq!(owner.lock().unwrap().authority_target(), expected);
            let attachment =
                crate::agent::supervisor_adapters::system_agent_supervisor_attachment_shared(
                    owner.clone(),
                    4,
                )
                .unwrap();
            let poisoned = owner.clone();
            assert!(
                std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                    let _guard = poisoned.lock().unwrap();
                    panic!("injected system lifecycle failure");
                }))
                .is_err()
            );
            assert_eq!(
                attachment.handle().authority_target(),
                Err(crate::agent::supervisor::AgentRouteError::Unavailable)
            );
            attachment.retire().unwrap();
            drop(poisoned);
            drop(owner);
            harness.stop();
        }

        #[inline(never)]
        fn check_dependent_lifecycle_recovery(
            harness: &mut NativeProjectionOwnerHarness,
            descriptor: AgentDescriptor,
            runtime: AdmittedRuntimePackage,
            scenario: u8,
        ) {
            let missing_predecessor_finalization = scenario == 21;
            let regressing_clock = scenario == 22;
            let live = scenario == 23;
            use crate::agent::local_lifecycle::{
                LocalLifecycleController, LocalLifecycleStoreFactory,
                discover_local_lifecycle_recovery,
            };
            struct Stores {
                space: SpaceId,
                agents: std::collections::BTreeMap<AgentId, (IssuerMemoryStore, IssuerMemoryStore)>,
            }
            impl LocalLifecycleStoreFactory for Stores {
                type Intent = IssuerMemoryStore;
                type Issuer = IssuerMemoryStore;
                type Error = ();
                fn discover(&mut self, space: SpaceId, maximum: usize) -> Result<Vec<AgentId>, ()> {
                    if space != self.space || self.agents.len() > maximum {
                        return Err(());
                    }
                    Ok(self.agents.keys().copied().collect())
                }
                fn open(
                    &mut self,
                    space: SpaceId,
                    agent: AgentId,
                ) -> Result<(Self::Intent, Self::Issuer), ()> {
                    self.open_existing(space, agent)
                }
                fn open_existing(
                    &mut self,
                    space: SpaceId,
                    agent: AgentId,
                ) -> Result<(Self::Intent, Self::Issuer), ()> {
                    if space != self.space {
                        return Err(());
                    }
                    self.agents.get(&agent).cloned().ok_or(())
                }
            }
            let mut second = descriptor.clone();
            second.creation_nonce = Hash([0xdd; 32]);
            second.identity.agent = AgentId::derive(
                second.identity.space,
                second.identity.owner,
                second.creation_nonce.as_bytes(),
            );
            let mut descriptors = [descriptor, second];
            descriptors.sort_by_key(|descriptor| std::cmp::Reverse(descriptor.identity.agent));
            assert!(descriptors[0].identity.agent > descriptors[1].identity.agent);
            let authority = harness.owner.as_ref().unwrap().authority_target();
            let key = SigningKey::from_bytes(&[CREDENTIAL_SEED; 32]);
            let calls: Vec<_> = descriptors
                .iter()
                .enumerate()
                .map(|(index, descriptor)| {
                    descriptor.validate().unwrap();
                    let request = ManagementRequest::Create(Box::new(descriptor.clone()));
                    let (mut call, _) = credential_call_and_approval(descriptor, &request, &key);
                    call.authority = authority;
                    call.request_sequence = NonZeroU64::new(index as u64 + 1).unwrap();
                    call.invocation = call.expected_invocation();
                    call.signature = key.sign(&call.signing_bytes()).to_bytes();
                    call
                })
                .collect();
            let root = harness._directory.0.join("dependent-local");
            let local = crate::agent::local_sdk_host::LocalAgentHost::create(
                &root,
                descriptors[0].identity.space,
                harness.fixture.plan.pins.node,
                harness.fixture.trust.clone(),
            )
            .unwrap();
            let mut stores = Stores {
                space: descriptors[0].identity.space,
                agents: descriptors
                    .iter()
                    .map(|descriptor| {
                        (
                            descriptor.identity.agent,
                            (IssuerMemoryStore::default(), IssuerMemoryStore::default()),
                        )
                    })
                    .collect(),
            };
            if scenario == 24 {
                stores
                    .agents
                    .get_mut(&descriptors[0].identity.agent)
                    .unwrap()
                    .0
                    .fail_retirement_after_commit =
                    Some(Arc::new(std::sync::atomic::AtomicBool::new(true)));
            }
            let mut controller = LocalLifecycleController::new(
                harness.owner.take().unwrap(),
                local,
                stores,
                CountingSigner::new(),
            )
            .unwrap();
            let initial = controller.ordered_index_for_test().unwrap();
            if matches!(scenario, 24 | 25) {
                #[inline(never)]
                fn check_retirement_retry(
                    mut controller: TestLocalLifecycle<Stores>,
                    descriptors: &[AgentDescriptor; 2],
                    calls: &[AuthorityCredentialCall],
                    runtime: &AdmittedRuntimePackage,
                    initial: u64,
                    prepared: bool,
                ) {
                    if prepared {
                        controller.fail_finalization_once_for_test(5);
                    }
                    assert_eq!(
                        controller.create(
                            descriptors[0].clone(),
                            calls[0].clone(),
                            runtime.clone()
                        ),
                        Err(SharedAgentHostError::Unavailable)
                    );
                    assert_eq!(
                        controller.ordered_index_for_test().unwrap(),
                        initial + if prepared { 0 } else { 4 }
                    );
                    assert_eq!(
                        controller.create(
                            descriptors[1].clone(),
                            calls[1].clone(),
                            runtime.clone()
                        ),
                        Err(SharedAgentHostError::Conflict)
                    );
                    let recovered = controller
                        .create(descriptors[0].clone(), calls[0].clone(), runtime.clone())
                        .unwrap();
                    recovered.1.verify_with(&RawCredentialVerifier).unwrap();
                    assert_eq!(controller.ordered_index_for_test().unwrap(), initial + 4);
                    let successor = controller
                        .create(descriptors[1].clone(), calls[1].clone(), runtime.clone())
                        .unwrap();
                    successor.1.verify_with(&RawCredentialVerifier).unwrap();
                    assert_eq!(controller.ordered_index_for_test().unwrap(), initial + 8);
                    assert_eq!(
                        controller
                            .create(descriptors[0].clone(), calls[0].clone(), runtime.clone())
                            .unwrap(),
                        recovered
                    );
                    assert_eq!(controller.ordered_index_for_test().unwrap(), initial + 8);
                }
                // Keep the setup fixture's large frames off the runtime's
                // normal-sized execution stack; do not raise stack limits.
                std::thread::scope(|scope| {
                    scope
                        .spawn(|| {
                            check_retirement_retry(
                                controller,
                                &descriptors,
                                &calls,
                                &runtime,
                                initial,
                                scenario == 25,
                            )
                        })
                        .join()
                        .unwrap()
                });
                return;
            }
            for index in if regressing_clock { [1, 0] } else { [0, 1] } {
                let descriptor = &descriptors[index];
                let call = &calls[index];
                if regressing_clock && index == 0 {
                    // Capture the successor first, then let its predecessor's
                    // saved finalization advance past that immutable clock.
                    harness
                        .fixture
                        .logical_slot
                        .as_ref()
                        .unwrap()
                        .store(LOGICAL_SLOT + 3, Ordering::Release);
                }
                // The predecessor has saved finalization at the same clock as
                // its successor's unaccepted authorization. A missing first
                // finalization instead must reject before startup dispatch.
                let failure = if index == 0 && !missing_predecessor_finalization && !live {
                    0
                } else {
                    5
                };
                if live {
                    controller.fail_finalization_once_for_test(failure);
                    assert_eq!(
                        controller.create(descriptor.clone(), call.clone(), runtime.clone()),
                        Err(if index == 0 {
                            SharedAgentHostError::Unavailable
                        } else {
                            SharedAgentHostError::Conflict
                        })
                    );
                    // The second request did not reach its fault hook.
                    controller.fail_finalization_once_for_test(255);
                } else {
                    // Historical overlapping stores must be constructed with
                    // the low-level test primitives: live capture now refuses
                    // to create this state. No production bypass is added.
                    let (mut owner, mut local, stores, mut signer) =
                        controller.into_parts_for_test();
                    let (intent_store, issuer_store) =
                        stores.agents[&descriptor.identity.agent].clone();
                    let mut slot =
                        crate::agent::clean_management_intent::CleanManagementIntentSlot::open(
                            intent_store,
                        )
                        .unwrap();
                    slot.pledge(
                        crate::agent::clean_management_intent::CleanManagementIntent::new(
                            authority,
                            call.managed,
                            ManagementRequest::Create(Box::new(descriptor.clone())),
                            call.clone(),
                            &RawCredentialVerifier,
                        )
                        .unwrap(),
                    )
                    .unwrap();
                    slot.retain_runtime(runtime.exact_bytes()).unwrap();
                    let mut issuer = DurableCleanManagementIssuer::open(
                        issuer_store,
                        descriptor.authority,
                        descriptor.identity.space,
                        descriptor.identity.agent,
                    )
                    .unwrap();
                    owner.fail_finalization_once_for_test(failure);
                    let result = owner
                        .create_local_from_management_intent(
                            &mut slot,
                            call.managed,
                            &mut local,
                            runtime.clone(),
                            &mut issuer,
                            &mut signer,
                        )
                        .and_then(|(_, ack)| {
                            owner.finalize_management_intent(
                                &mut slot,
                                call.managed,
                                &ack,
                                &mut issuer,
                            )
                        });
                    assert_eq!(result, Err(SharedAgentHostError::Unavailable));
                    controller =
                        LocalLifecycleController::new(owner, local, stores, signer).unwrap();
                }
            }
            assert_eq!(
                controller.ordered_index_for_test().unwrap(),
                initial + u64::from(!missing_predecessor_finalization && !live)
            );
            harness
                .fixture
                .logical_slot
                .as_ref()
                .unwrap()
                .store(LOGICAL_SLOT + 3, Ordering::Release);
            if missing_predecessor_finalization || regressing_clock {
                let (owner, local, mut stores, _) = controller.into_parts_for_test();
                let before: Vec<_> = stores
                    .agents
                    .values()
                    .map(|(intent, issuer)| {
                        (
                            intent.image.lock().unwrap().clone(),
                            issuer.image.lock().unwrap().clone(),
                        )
                    })
                    .collect();
                let recovery =
                    discover_local_lifecycle_recovery(&mut stores, authority, 2).unwrap();
                assert!(matches!(
                    recovery.startup_admission(),
                    Err(SharedAgentHostError::Conflict)
                ));
                let after: Vec<_> = stores
                    .agents
                    .values()
                    .map(|(intent, issuer)| {
                        (
                            intent.image.lock().unwrap().clone(),
                            issuer.image.lock().unwrap().clone(),
                        )
                    })
                    .collect();
                assert_eq!(before, after);
                assert_eq!(
                    owner.ordered_index_for_test().unwrap(),
                    initial + u64::from(regressing_clock)
                );
                assert_eq!(local.list().unwrap().len(), usize::from(regressing_clock));
                return;
            }
            #[inline(never)]
            fn restart(
                controller: TestLocalLifecycle<Stores>,
                harness: &NativeProjectionOwnerHarness,
                root: &Path,
                attempt: usize,
                live: bool,
            ) -> TestLocalLifecycle<Stores> {
                let (old_owner, old_local, mut stores, mut signer) =
                    controller.into_parts_for_test();
                let before = old_owner.ordered_index_for_test().unwrap();
                let pins = old_owner._pins_store.clone();
                let record = old_owner.record_store.clone();
                let issuer = old_owner.issuer.into_store();
                drop(old_owner._network_host);
                drop(old_owner.host);
                drop(old_local);
                let recovery = discover_local_lifecycle_recovery(
                    &mut stores,
                    harness.fixture.plan.authority_target(),
                    2,
                )
                .unwrap();
                assert_eq!(recovery.entries.len(), 2);
                assert!(recovery.entries[0].agent < recovery.entries[1].agent);
                assert_eq!(
                    recovery.entries[0]
                        .intent
                        .intent()
                        .unwrap()
                        .call()
                        .request_sequence
                        .get(),
                    2
                );
                let admission = recovery.startup_admission().unwrap();
                assert!(admission.retirements.is_empty());
                assert_eq!(
                    admission.pending.len(),
                    if attempt == 0 {
                        if live { 1 } else { 2 }
                    } else {
                        0
                    }
                );
                let reopened = CleanSystemAgentBootstrapOwner::open_or_bootstrap_with_factory(
                    pins,
                    record,
                    issuer,
                    &mut signer,
                    || panic!("recovery cannot create a fresh bootstrap plan"),
                    harness._directory.host(),
                    harness._directory.lock(),
                    harness.fixture.plan.pins.space,
                    harness.fixture.plan.pins.node,
                    harness.fixture.trust.clone(),
                    harness.fixture.merge.clone(),
                    harness.fixture.finality.clone(),
                    harness.provider.clone(),
                    harness.network.clone(),
                    Some(&admission),
                )
                .unwrap();
                assert_eq!(reopened.ordered_index_for_test().unwrap(), before);
                let local = crate::agent::local_sdk_host::LocalAgentHost::open(
                    root,
                    stores.space,
                    harness.fixture.plan.pins.node,
                    harness.fixture.trust.clone(),
                )
                .unwrap();
                let controller = LocalLifecycleController::with_recovery(
                    reopened, local, stores, signer, recovery,
                )
                .unwrap();
                // One remaining authorization, two finalizations, four ACKs.
                assert_eq!(
                    controller.ordered_index_for_test().unwrap(),
                    before
                        + if attempt == 0 {
                            if live { 4 } else { 7 }
                        } else {
                            0
                        }
                );
                controller
            }
            let mut acknowledgements = Vec::new();
            for attempt in 0..2 {
                controller = std::thread::scope(|scope| {
                    scope
                        .spawn(|| restart(controller, harness, &root, attempt, live))
                        .join()
                        .unwrap()
                });
                let before = controller.ordered_index_for_test().unwrap();
                for (index, (descriptor, call)) in descriptors.iter().zip(&calls).enumerate() {
                    let result = controller
                        .create(descriptor.clone(), call.clone(), runtime.clone())
                        .unwrap();
                    assert_eq!(result.0, descriptor.identity.agent);
                    assert_eq!(result.1.credential_call, call.commitment());
                    result.1.verify_with(&RawCredentialVerifier).unwrap();
                    if attempt == 0 {
                        acknowledgements.push(result);
                    } else {
                        assert_eq!(result, acknowledgements[index]);
                    }
                }
                assert_eq!(
                    controller.ordered_index_for_test().unwrap(),
                    before + if live && attempt == 0 { 4 } else { 0 }
                );
            }
            let (_, local, stores, _) = controller.into_parts_for_test();
            assert_eq!(local.list().unwrap().len(), 2);
            for (intent, _) in stores.agents.into_values() {
                assert!(
                    crate::agent::clean_management_intent::CleanManagementIntentSlot::open(intent)
                        .unwrap()
                        .retirement_complete()
                        .unwrap()
                );
            }
        }

        #[inline(never)]
        fn check_management_denial_evidence(
            harness: &mut NativeProjectionOwnerHarness,
            descriptor: AgentDescriptor,
            mut call: AuthorityCredentialCall,
            runtime: AdmittedRuntimePackage,
            scenario: u8,
        ) {
            let denied = scenario != 27;
            if denied {
                // A genuine signed request with an unavailable next sequence:
                // policy returns canonical empty bytes, not a runtime failure.
                call.request_sequence = NonZeroU64::new(2).unwrap();
                call.invocation = call.expected_invocation();
                call.signature = SigningKey::from_bytes(&[CREDENTIAL_SEED; 32])
                    .sign(&call.signing_bytes())
                    .to_bytes();
            }
            let mut owner = harness.owner.take().unwrap();
            let mut local = crate::agent::local_sdk_host::LocalAgentHost::create(
                &harness._directory.0.join("denial-local"),
                descriptor.identity.space,
                owner.pins.node,
                harness.fixture.trust.clone(),
            )
            .unwrap();
            let mut intent_store = IssuerMemoryStore::default();
            let issuer_store = IssuerMemoryStore::default();
            let mut signer = CountingSigner::new();
            if scenario == 30 {
                intent_store.fail_retirement_after_commit =
                    Some(Arc::new(std::sync::atomic::AtomicBool::new(true)));
            }
            signer.fail_denial = matches!(scenario, 29 | 31);
            let before = owner.ordered_index_for_test().unwrap();
            if scenario < 28 {
                owner.fail_finalization_once_for_test(if denied { 8 } else { 6 });
            }
            assert_eq!(
                owner.create_local_agent(
                    intent_store.clone(),
                    issuer_store.clone(),
                    descriptor.clone(),
                    call.clone(),
                    &mut local,
                    runtime.clone(),
                    &mut signer
                ),
                Err(if denied && scenario < 29 {
                    SharedAgentHostError::ScopeMismatch
                } else {
                    SharedAgentHostError::Unavailable
                })
            );
            if scenario >= 28 {
                assert_eq!(owner.ordered_index_for_test().unwrap(), before + 2);
                assert_eq!(signer.calls, 1);
                assert!(local.list().unwrap().is_empty());
                assert!(issuer_store.image.lock().unwrap().is_none());
                if scenario == 31 {
                    #[inline(never)]
                    fn restart_denial(
                        old: MemoryBootstrapOwner,
                        local: crate::agent::local_sdk_host::LocalAgentHost,
                        mut signer: CountingSigner,
                        harness: &NativeProjectionOwnerHarness,
                        descriptor: &AgentDescriptor,
                        intent: IssuerMemoryStore,
                        issuer: IssuerMemoryStore,
                    ) -> (
                        MemoryBootstrapOwner,
                        crate::agent::local_sdk_host::LocalAgentHost,
                        CountingSigner,
                    ) {
                        struct Stores {
                            scope: (SpaceId, AgentId),
                            intent: IssuerMemoryStore,
                            issuer: IssuerMemoryStore,
                        }
                        impl crate::agent::local_lifecycle::LocalLifecycleStoreFactory for Stores {
                            type Intent = IssuerMemoryStore;
                            type Issuer = IssuerMemoryStore;
                            type Error = ();
                            fn discover(
                                &mut self,
                                space: SpaceId,
                                maximum: usize,
                            ) -> Result<Vec<AgentId>, ()> {
                                if space != self.scope.0 || maximum < 1 {
                                    return Err(());
                                }
                                Ok(vec![self.scope.1])
                            }
                            fn open(
                                &mut self,
                                space: SpaceId,
                                agent: AgentId,
                            ) -> Result<(Self::Intent, Self::Issuer), ()>
                            {
                                if (space, agent) != self.scope {
                                    return Err(());
                                }
                                Ok((self.intent.clone(), self.issuer.clone()))
                            }
                            fn open_existing(
                                &mut self,
                                space: SpaceId,
                                agent: AgentId,
                            ) -> Result<(Self::Intent, Self::Issuer), ()>
                            {
                                self.open(space, agent)
                            }
                        }
                        let before = old.ordered_index_for_test().unwrap();
                        let pins = old._pins_store.clone();
                        let record = old.record_store.clone();
                        let bootstrap_issuer = old.issuer.into_store();
                        drop(old._network_host);
                        drop(old.host);
                        drop(local);
                        let mut stores = Stores {
                            scope: (descriptor.identity.space, descriptor.identity.agent),
                            intent,
                            issuer,
                        };
                        let pending = usize::from(
                            !stores
                                .intent
                                .image
                                .lock()
                                .unwrap()
                                .as_ref()
                                .unwrap()
                                .starts_with(b"CND1"),
                        );
                        let recovery =
                            crate::agent::local_lifecycle::discover_local_lifecycle_recovery(
                                &mut stores,
                                harness.fixture.plan.authority_target(),
                                1,
                            )
                            .unwrap();
                        let admission = recovery.startup_admission().unwrap();
                        assert_eq!(admission.pending.len(), pending);
                        let owner = CleanSystemAgentBootstrapOwner::open_or_bootstrap_with_factory(
                            pins,
                            record,
                            bootstrap_issuer,
                            &mut signer,
                            || panic!("denial recovery cannot bootstrap"),
                            harness._directory.host(),
                            harness._directory.lock(),
                            harness.fixture.plan.pins.space,
                            harness.fixture.plan.pins.node,
                            harness.fixture.trust.clone(),
                            harness.fixture.merge.clone(),
                            harness.fixture.finality.clone(),
                            harness.provider.clone(),
                            harness.network.clone(),
                            Some(&admission),
                        )
                        .unwrap();
                        let local = crate::agent::local_sdk_host::LocalAgentHost::open(
                            &harness._directory.0.join("denial-local"),
                            descriptor.identity.space,
                            harness.fixture.plan.pins.node,
                            harness.fixture.trust.clone(),
                        )
                        .unwrap();
                        let controller =
                            crate::agent::local_lifecycle::LocalLifecycleController::with_recovery(
                                owner, local, stores, signer, recovery,
                            )
                            .unwrap();
                        assert_eq!(controller.ordered_index_for_test().unwrap(), before);
                        let (owner, local, _, signer) = controller.into_parts_for_test();
                        (owner, local, signer)
                    }
                    for _ in 0..2 {
                        (owner, local, signer) = std::thread::scope(|scope| {
                            scope
                                .spawn(|| {
                                    restart_denial(
                                        owner,
                                        local,
                                        signer,
                                        harness,
                                        &descriptor,
                                        intent_store.clone(),
                                        issuer_store.clone(),
                                    )
                                })
                                .join()
                                .unwrap()
                        });
                    }
                }
                #[cfg(all(
                    target_os = "linux",
                    feature = "storage",
                    feature = "experimental-state-blocks"
                ))]
                if scenario == 29 {
                    // Complete the same denied signed Create through an
                    // exact-intent external file slot after the image-path
                    // signer failed. No external journal may have appeared;
                    // the Authority result retirement is shared.
                    let directory = harness._directory.0.join("denial-external");
                    std::fs::create_dir(&directory).unwrap();
                    let agent_hex = descriptor
                        .identity
                        .agent
                        .0
                        .iter()
                        .map(|byte| format!("{byte:02x}"))
                        .collect::<String>();
                    let agent_root = directory.join(format!("{agent_hex}.agent"));
                    let agent_lock = directory.join(format!("{agent_hex}.agent-lock"));
                    let parent = std::fs::File::open(&directory).unwrap();
                    let mut slot =
                        crate::agent::clean_management_intent::CleanManagementIntentSlot::open(
                            intent_store.clone(),
                        )
                        .unwrap();
                    let intent_hash =
                        crate::agent::external_local_executor::external_local_create_intent_hash(
                            slot.intent().unwrap(),
                        );
                    let external = crate::agent::journal_store::FileLocalAgentJournalSlot::acquire_with_pinned_parents(
                        agent_root,
                        agent_lock,
                        crate::service::NodeId(owner.pins.node.0),
                        intent_hash,
                        &parent,
                        &parent,
                    )
                    .unwrap();
                    let issuer = DurableCleanManagementIssuer::open(
                        issuer_store.clone(),
                        descriptor.authority,
                        descriptor.identity.space,
                        descriptor.identity.agent,
                    )
                    .unwrap();
                    external.verify_absent().unwrap();
                    assert!(
                        owner
                            .finish_denied_external_local_intent(
                                &mut slot,
                                &issuer,
                                &external,
                                &mut signer,
                            )
                            .unwrap()
                    );
                    assert!(slot.denial_complete().unwrap());
                    external.verify_absent().unwrap();
                }
                if scenario >= 29 {
                    assert_eq!(
                        owner.create_local_agent(
                            intent_store.clone(),
                            issuer_store.clone(),
                            descriptor.clone(),
                            call.clone(),
                            &mut local,
                            runtime.clone(),
                            &mut signer
                        ),
                        Err(SharedAgentHostError::ScopeMismatch)
                    );
                    assert_eq!(owner.ordered_index_for_test().unwrap(), before + 2);
                }
                let signatures = if matches!(scenario, 29 | 31) { 2 } else { 1 };
                assert_eq!(signer.calls, signatures);
                let image = intent_store.image.lock().unwrap().clone().unwrap();
                assert!(image.starts_with(b"CND1"));
                let submission = crate::agent::local_lifecycle::LocalCreateSubmission::new(
                    descriptor.clone(),
                    call.clone(),
                    runtime.clone(),
                )
                .unwrap();
                let verified_denial = submission.verify_denial(&image).unwrap();
                assert_eq!(verified_denial.exact_bytes(), image);
                assert!(submission.verify_denial(&image[..image.len() - 1]).is_err());
                let mut trailing = image.clone();
                trailing.push(0);
                assert!(submission.verify_denial(&trailing).is_err());
                assert!(
                    submission
                        .verify_denial(&vec![
                            0;
                            crate::agent::local_lifecycle::LocalCreateDenial::MAX_BYTES
                                + 1
                        ])
                        .is_err()
                );
                assert!(
                    crate::agent::clean_management_intent::CleanManagementIntentSlot::open(
                        intent_store.clone()
                    )
                    .unwrap()
                    .denial_complete()
                    .unwrap()
                );
                assert_eq!(
                    owner.create_local_agent(
                        intent_store.clone(),
                        issuer_store.clone(),
                        descriptor.clone(),
                        call.clone(),
                        &mut local,
                        runtime.clone(),
                        &mut signer
                    ),
                    Err(SharedAgentHostError::ScopeMismatch)
                );
                assert_eq!(signer.calls, signatures);
                assert_eq!(owner.ordered_index_for_test().unwrap(), before + 2);
                let mut corrupt = image.clone();
                *corrupt.last_mut().unwrap() ^= 1;
                assert!(submission.verify_denial(&corrupt).is_err());
                let mut wrong_domain = image.clone();
                wrong_domain[..4].copy_from_slice(b"CMR2");
                assert!(submission.verify_denial(&wrong_domain).is_err());
                let corrupt_store = IssuerMemoryStore::default();
                *corrupt_store.image.lock().unwrap() = Some(corrupt);
                assert!(
                    crate::agent::clean_management_intent::CleanManagementIntentSlot::open(
                        corrupt_store
                    )
                    .is_err()
                );
                let mut next = descriptor.clone();
                next.creation_nonce = Hash([0xb9; 32]);
                next.identity.agent = AgentId::derive(
                    next.identity.space,
                    next.identity.owner,
                    next.creation_nonce.as_bytes(),
                );
                let key = SigningKey::from_bytes(&[CREDENTIAL_SEED; 32]);
                let (mut next_call, _) = credential_call_and_approval(
                    &next,
                    &ManagementRequest::Create(Box::new(next.clone())),
                    &key,
                );
                next_call.authority = owner.authority_target();
                next_call.invocation = next_call.expected_invocation();
                next_call.signature = key.sign(&next_call.signing_bytes()).to_bytes();
                let next_submission = crate::agent::local_lifecycle::LocalCreateSubmission::new(
                    next.clone(),
                    next_call.clone(),
                    runtime.clone(),
                )
                .unwrap();
                assert!(next_submission.verify_denial(&image).is_err());
                let result = owner
                    .create_local_agent(
                        IssuerMemoryStore::default(),
                        IssuerMemoryStore::default(),
                        next.clone(),
                        next_call,
                        &mut local,
                        runtime,
                        &mut signer,
                    )
                    .unwrap();
                assert_eq!(result.0, next.identity.agent);
                result.1.verify_with(&RawCredentialVerifier).unwrap();
                assert_eq!(owner.ordered_index_for_test().unwrap(), before + 6);
                assert_eq!(local.list().unwrap().len(), 1);
                assert_eq!(*intent_store.image.lock().unwrap(), Some(image));
                std::thread::scope(|scope| {
                    scope
                        .spawn(|| {
                            use crate::agent::local_lifecycle::{
                                LocalLifecycleController, LocalLifecycleStoreFactory,
                                NativeLocalLifecycle,
                            };
                            struct Stores(SpaceId, AgentId, IssuerMemoryStore, IssuerMemoryStore);
                            impl LocalLifecycleStoreFactory for Stores {
                                type Intent = IssuerMemoryStore;
                                type Issuer = IssuerMemoryStore;
                                type Error = ();
                                fn discover(
                                    &mut self,
                                    space: SpaceId,
                                    maximum: usize,
                                ) -> Result<Vec<AgentId>, ()> {
                                    if space != self.0 || maximum == 0 {
                                        return Err(());
                                    }
                                    Ok(vec![self.1])
                                }
                                fn open_existing(
                                    &mut self,
                                    space: SpaceId,
                                    agent: AgentId,
                                ) -> Result<(Self::Intent, Self::Issuer), ()>
                                {
                                    if (space, agent) != (self.0, self.1) {
                                        return Err(());
                                    }
                                    Ok((self.2.clone(), self.3.clone()))
                                }
                                fn open(
                                    &mut self,
                                    space: SpaceId,
                                    agent: AgentId,
                                ) -> Result<(Self::Intent, Self::Issuer), ()>
                                {
                                    self.open_existing(space, agent)
                                }
                            }
                            let stores = Stores(
                                descriptor.identity.space,
                                descriptor.identity.agent,
                                intent_store,
                                issuer_store,
                            );
                            let mut controller =
                                LocalLifecycleController::new(owner, local, stores, signer)
                                    .unwrap();
                            assert!(controller.retained_denial(&submission).unwrap().is_none());
                            let (descriptor, call, runtime) =
                                crate::agent::local_lifecycle::LocalCreateSubmission::decode(
                                    &submission.encode(),
                                )
                                .unwrap()
                                .into_parts();
                            assert_eq!(
                                controller.create(descriptor, call, runtime),
                                Err(SharedAgentHostError::ScopeMismatch)
                            );
                            assert_eq!(
                                controller.retained_denial(&submission).unwrap(),
                                Some(verified_denial)
                            );
                            assert!(
                                controller
                                    .retained_denial(&next_submission)
                                    .unwrap()
                                    .is_none()
                            );
                            assert_eq!(controller.ordered_index_for_test().unwrap(), before + 6);
                        })
                        .join()
                        .unwrap();
                });
                return;
            }
            assert_eq!(owner.ordered_index_for_test().unwrap(), before + 1);
            assert_eq!(signer.calls, 0);
            assert!(local.list().unwrap().is_empty());
            let intent_image = intent_store.image.lock().unwrap().clone();
            let issuer_image = issuer_store.image.lock().unwrap().clone();
            let slot = crate::agent::clean_management_intent::CleanManagementIntentSlot::open(
                intent_store.clone(),
            )
            .unwrap();
            let issuer = DurableCleanManagementIssuer::open(
                issuer_store.clone(),
                descriptor.authority,
                descriptor.identity.space,
                descriptor.identity.agent,
            )
            .unwrap();
            let agent = HostAgentId(owner.pins.agent.0);
            for attempt in 0..2 {
                if attempt == 1 {
                    assert!(owner._network_host.mark_stale_for_test(agent));
                    owner._network_host.refresh().unwrap();
                }
                let proof = owner
                    .verify_management_denial(&slot, &issuer, &local)
                    .unwrap();
                assert_eq!(proof.is_some(), denied);
                if let Some(proof) = proof {
                    assert_eq!(proof.call, call.commitment());
                    assert_eq!(&proof.anchor, slot.authorization_anchor().unwrap().unwrap());
                    assert_eq!(&proof.work, slot.authorization_work().unwrap().unwrap());
                    assert_eq!(
                        Some(proof.input),
                        owner
                            .host
                            .lock()
                            .unwrap()
                            .management_invocation_after_anchor(agent, &proof.anchor, &proof.work)
                            .unwrap()
                    );
                }
                assert_eq!(owner.ordered_index_for_test().unwrap(), before + 1);
                assert_eq!(*intent_store.image.lock().unwrap(), intent_image);
                assert_eq!(*issuer_store.image.lock().unwrap(), issuer_image);
                assert_eq!(signer.calls, 0);
                // Evidence collection must not release or retire anything.
                owner
                    ._network_host
                    .ensure_management_pending_member(
                        agent,
                        slot.authorization_anchor().unwrap().unwrap(),
                        slot.authorization_work().unwrap().unwrap(),
                    )
                    .unwrap();
            }
            let wrong_issuer = DurableCleanManagementIssuer::open(
                IssuerMemoryStore::default(),
                descriptor.authority,
                descriptor.identity.space,
                AgentId([0x59; 32]),
            )
            .unwrap();
            assert!(matches!(
                owner.verify_management_denial(&slot, &wrong_issuer, &local),
                Err(SharedAgentHostError::ScopeMismatch)
            ));
            assert_eq!(owner.ordered_index_for_test().unwrap(), before + 1);
        }

