        #[cfg(feature = "experimental-state-blocks")]
        fn native_candidate_state_authority_fixture(target: &Path) -> PhysicalFixture {
            let mut package =
                PackageEnvelope::decode(include_bytes!("../../../vosx/blobs/system_authority.vos"))
                    .unwrap();
            let program = vos_pvm_compiler::link_elf_spi(
                &std::fs::read(
                    target.join("agent-state-authority/riscv64em-vos/release/system_authority.elf"),
                )
                .expect("build experimental Authority guest first"),
            )
            .unwrap();
            let program_ref = BlobRef::of_bytes(&program);
            let PackageManifest::Actor(manifest) = &mut package.manifest else {
                unreachable!()
            };
            let old_program = core::mem::replace(&mut manifest.program, program_ref.clone());
            package
                .artifacts
                .retain(|artifact| artifact.identity != old_program);
            package.artifacts.push(PackageArtifact {
                identity: program_ref,
                bytes: program,
            });
            package
                .artifacts
                .sort_unstable_by(|left, right| left.identity.cmp(&right.identity));
            let key = SigningKey::from_bytes(&[RECEIPT_SEED; 32]);
            let public_key = key.verifying_key().to_bytes();
            *package.manifest.signing_mut() = PackageSigning {
                producer: ProducerId::of_public_key(&public_key),
                public_key,
                signature: [0; 64],
            };
            package.manifest.signing_mut().signature =
                key.sign(&package.signing_bytes().unwrap()).to_bytes();
            native_authority_package_fixture(false, &package.encode().unwrap())
        }

        #[test]
        #[ignore = "requires AUTHORITY_CANDIDATE_ELF; executes candidate bootstrap and file-journal reopen"]
        fn candidate_authority_real_bootstrap_reopens_file_journal() {
            let package = candidate_authority_package();
            let fixture = native_authority_package_fixture(false, &package);
            check_candidate_authority_real_bootstrap_reopens_file_journal(fixture);
        }

        fn candidate_authority_package() -> Vec<u8> {
            let elf = std::fs::read(std::env::var("AUTHORITY_CANDIDATE_ELF").unwrap()).unwrap();
            let program = vos_pvm_compiler::link_elf_spi(&elf).unwrap();
            let schema = crate::agent::schema::raw_section_from_elf(&elf).unwrap();
            let mut package =
                PackageEnvelope::decode(include_bytes!("../../../vosx/blobs/system_authority.vos"))
                    .unwrap();
            let PackageManifest::Actor(manifest) = &mut package.manifest else {
                unreachable!()
            };
            let old_program =
                core::mem::replace(&mut manifest.program, BlobRef::of_bytes(&program));
            let old_schema =
                core::mem::replace(&mut manifest.state_lane_schema, BlobRef::of_bytes(&schema));
            package.artifacts.retain(|artifact| {
                artifact.identity != old_program && artifact.identity != old_schema
            });
            for bytes in [program, schema] {
                package.artifacts.push(PackageArtifact {
                    identity: BlobRef::of_bytes(&bytes),
                    bytes,
                });
            }
            package
                .artifacts
                .sort_unstable_by(|a, b| a.identity.cmp(&b.identity));
            // Bind the complete new program/schema closure to the fixture issuer.
            let key = SigningKey::from_bytes(&[RECEIPT_SEED; 32]);
            let public_key = key.verifying_key().to_bytes();
            *package.manifest.signing_mut() = PackageSigning {
                producer: ProducerId::of_public_key(&public_key),
                public_key,
                signature: [0; 64],
            };
            package.manifest.signing_mut().signature =
                key.sign(&package.signing_bytes().unwrap()).to_bytes();
            package.encode().unwrap()
        }

        fn check_candidate_authority_real_bootstrap_reopens_file_journal(fixture: PhysicalFixture) {
            let directory = TestDirectory::new("candidate-authority-real-bootstrap");
            let network = network(NODE_SEED);
            let pins = BootstrapMemoryStore::default();
            let record = BootstrapMemoryStore {
                bootstrap_clock: Some(fixture.logical_slot.as_ref().unwrap().clone()),
                ..BootstrapMemoryStore::default()
            };
            let issuer = IssuerMemoryStore::default();
            let provider = Arc::new(MemoryProvider::new(fixture.provision.clone()));
            let mut signer = CountingSigner::new();
            let mut owner = open_owner(
                &fixture,
                &directory,
                pins.clone(),
                record.clone(),
                issuer.clone(),
                &mut signer,
                provider.clone(),
                network.clone(),
            )
            .unwrap();
            let public = SigningKey::from_bytes(&[CREDENTIAL_SEED; 32])
                .verifying_key()
                .to_bytes();
            let (node_key, _, _, node) = node_material();
            let mut query = AuthorityProjectionQuery {
                authority: owner.authority_target(),
                credential: CredentialId::of_public_key(&public),
                nonce: Hash([0xdd; 32]),
                selector: AuthorityProjectionSelector::Credential,
                recovery: None,
                authentication: AuthorityIngressAuthentication::SshNodeAttestation {
                    credential_public_key: public,
                    node: NodeId(node.0),
                    request_binding: Hash([0xde; 32]),
                    signature: [1; 64],
                },
            };
            let signature = node_key.sign(&query.signing_bytes()).to_bytes();
            if let AuthorityIngressAuthentication::SshNodeAttestation {
                signature: value, ..
            } = &mut query.authentication
            {
                *value = signature;
            }
            let response = owner.invoke_authority_projection(query.clone()).unwrap();
            AuthorityCredentialProjection::decode(&response)
                .unwrap()
                .validate_shape()
                .unwrap();
            let physical = native_owner_physical_state(&owner);
            drop(owner);
            let mut reopened = open_owner(
                &fixture,
                &directory,
                pins,
                record,
                issuer,
                &mut signer,
                provider,
                network.clone(),
            )
            .unwrap();
            let (position, commitment, mut status) = native_owner_physical_state(&reopened);
            assert_eq!(position, physical.0);
            assert_eq!(commitment, physical.1);
            // Reattaching Raft can append its leader no-op without publishing
            // another runtime operation. Compare all durable identity/status
            // fields while accounting for that physical slot consumption.
            assert!(status.applied_slots >= physical.2.applied_slots);
            assert_eq!(
                status.applied_slots + status.remaining_slots,
                physical.2.applied_slots + physical.2.remaining_slots
            );
            status.applied_slots = physical.2.applied_slots;
            status.remaining_slots = physical.2.remaining_slots;
            assert_eq!(status, physical.2);
            // The first read's Invoke/ACK pair is already retired. A fresh
            // inspection needs a fresh signed nonce, not that retired ID.
            let original_query = query.clone();
            query.nonce = Hash([0xdf; 32]);
            let signature = node_key.sign(&query.signing_bytes()).to_bytes();
            if let AuthorityIngressAuthentication::SshNodeAttestation {
                signature: value, ..
            } = &mut query.authentication
            {
                *value = signature;
            }
            let fresh = reopened.invoke_authority_projection(query).unwrap();
            let mut projection = AuthorityCredentialProjection::decode(&fresh).unwrap();
            projection.validate_shape().unwrap();
            projection.query = original_query;
            assert_eq!(
                projection,
                AuthorityCredentialProjection::decode(&response).unwrap()
            );
            drop(reopened);
            stop_network(network);
        }

        #[test]
        fn pending_system_bootstrap_retains_attachment_and_requires_reopen_after_store_error() {
            for fail_store in [false, true] {
                let fixture = native_bundled_authority_fixture();
                let directory = TestDirectory::new("pending-system-bootstrap");
                let network = network(NODE_SEED);
                let pins = BootstrapMemoryStore::default();
                let record = BootstrapMemoryStore {
                    bootstrap_clock: fixture.logical_slot.clone(),
                    ..BootstrapMemoryStore::default()
                };
                let issuer = IssuerMemoryStore::default();
                let provider = Arc::new(MemoryProvider::new(fixture.provision.clone()));
                let mut signer = CountingSigner::new();
                let mut pending = CleanSystemAgentBootstrapOwner::attach_bootstrap_with_admission(
                    pins.clone(),
                    record.clone(),
                    issuer.clone(),
                    &mut signer,
                    &fixture.plan,
                    directory.host(),
                    directory.lock(),
                    fixture.plan.pins.space,
                    fixture.plan.pins.node,
                    fixture.trust.clone(),
                    fixture.merge.clone(),
                    fixture.finality.clone(),
                    provider.clone(),
                    network.clone(),
                    None,
                    None,
                )
                .unwrap();
                let attached = pending.owner.as_ref().unwrap();
                let host = Arc::downgrade(&attached.host);
                assert_eq!(
                    attached.record.phase(),
                    CleanSystemAgentBootstrapPhase::CreateReceiptIssued
                );
                assert!(
                    inspect_actor(
                        &attached.host,
                        &fixture.plan,
                        fixture.plan.pins.authority.issuer.actor
                    )
                    .unwrap()
                    .is_none()
                );
                if fail_store {
                    record.fail_next_before_publish();
                    assert!(matches!(
                        pending.try_complete(&mut signer),
                        Err(CleanSystemAgentBootstrapError::RecordStorage)
                    ));
                    assert!(host.upgrade().is_some());
                    let commits = record.commits();
                    assert!(matches!(
                        pending.try_complete(&mut signer),
                        Err(CleanSystemAgentBootstrapError::Rejected(
                            CleanSystemAgentBootstrapRejection::InvalidRecord
                        ))
                    ));
                    assert_eq!(record.commits(), commits);
                    drop(pending);
                    assert!(host.upgrade().is_none());
                    let owner = open_owner(
                        &fixture,
                        &directory,
                        pins,
                        record,
                        issuer,
                        &mut signer,
                        provider,
                        network.clone(),
                    )
                    .unwrap();
                    assert_eq!(
                        owner.record.phase(),
                        CleanSystemAgentBootstrapPhase::Complete
                    );
                    drop(owner);
                } else {
                    let owner = pending.try_complete(&mut signer).unwrap().unwrap();
                    assert_eq!(
                        owner.record.phase(),
                        CleanSystemAgentBootstrapPhase::Complete
                    );
                    assert!(pending.try_complete(&mut signer).unwrap().is_none());
                    drop(pending);
                    assert!(host.upgrade().is_some());
                    drop(owner);
                    assert!(host.upgrade().is_none());
                }
                stop_network(network);
            }
        }

