        fn check_bundled_authority_fresh_query(inventory: bool) {
            if std::env::var_os("VOS_TEST_BOOTSTRAP_DIAGNOSTICS").is_some() {
                let _ = tracing_subscriber::fmt()
                    .with_env_filter("vos::agent=debug,vos_pvm::refine_host=debug")
                    .try_init();
            }
            let mut harness = NativeProjectionOwnerHarness::with_fixture(
                "bundled-authority-fresh-query",
                native_bundled_authority_fixture(),
            );
            let owner = harness.owner.as_mut().unwrap();
            let credential_key = SigningKey::from_bytes(&[CREDENTIAL_SEED; 32]);
            let public = credential_key.verifying_key().to_bytes();
            let (node_key, _, _, node) = node_material();
            let mut query = AuthorityProjectionQuery {
                authority: owner.authority_target(),
                credential: CredentialId::of_public_key(&public),
                nonce: Hash([0xd5; 32]),
                recovery: None,
                selector: if inventory {
                    AuthorityProjectionSelector::Inventory {
                        after: None,
                        limit: 64,
                        known_head: None,
                    }
                } else {
                    AuthorityProjectionSelector::Credential
                },
                authentication: AuthorityIngressAuthentication::SshNodeAttestation {
                    credential_public_key: public,
                    node: NodeId(node.0),
                    request_binding: Hash([0xd6; 32]),
                    signature: [1; 64],
                },
            };
            let signature = node_key.sign(&query.signing_bytes()).to_bytes();
            if let AuthorityIngressAuthentication::SshNodeAttestation {
                signature: value, ..
            } = &mut query.authentication
            {
                *value = signature;
            }
            let pending = owner.prepare_authority_projection(query.clone()).unwrap();
            let (work, authorization) = pending.invocation().unwrap();
            let agent = HostAgentId(owner.pins.agent.0);
            assert!(owner.record.pending_projection.is_none());
            assert!(
                !owner
                    .host
                    .lock()
                    .unwrap()
                    .retained_positive_clean_acknowledgement(agent, work, authorization)
                    .unwrap()
            );
            // With VOS_AGENT_PROFILE_REFINE_MACHINES set, the fixture uses
            // the bundled outer PVM too. These markers separate this fresh
            // query's Invoke/ACK from bootstrap/replay machine observations.
            eprintln!("bundled_authority_fresh_query begin");
            let query_started = std::time::Instant::now();
            let response = owner.invoke_authority_projection(query.clone()).unwrap();
            eprintln!(
                "bundled_authority_fresh_query end elapsed_us={}",
                query_started.elapsed().as_micros()
            );
            let projection = if inventory {
                let page = crate::agent_sdk::authority::AuthorityInventoryProjectionPage::decode(
                    &response,
                )
                .unwrap();
                page.validate_shape().unwrap();
                assert!(!page.unchanged);
                assert!(page.next.is_none());
                page.credential
            } else {
                AuthorityCredentialProjection::decode(&response).unwrap()
            };
            projection.validate_shape().unwrap();
            assert_eq!(projection.query, query);
            assert_eq!(projection.status, AuthorityCredentialStatus::Active);
            assert_eq!(projection.principal, owner.pins.descriptor.identity.owner);
            assert!(owner.record.pending_projection.is_none());
            assert!(
                owner
                    .host
                    .lock()
                    .unwrap()
                    .retained_positive_clean_acknowledgement(agent, work, authorization)
                    .unwrap()
            );
            if inventory {
                query.nonce = Hash([0xd7; 32]);
                query.selector = AuthorityProjectionSelector::Inventory {
                    after: None,
                    limit: 64,
                    known_head: Some(projection.head),
                };
                let signature = node_key.sign(&query.signing_bytes()).to_bytes();
                if let AuthorityIngressAuthentication::SshNodeAttestation {
                    signature: value, ..
                } = &mut query.authentication
                {
                    *value = signature;
                }
                let before = owner.ordered_index_for_test().unwrap();
                let pending = owner.prepare_authority_projection(query.clone()).unwrap();
                let (work, authorization) = pending.invocation().unwrap();
                let response = owner.invoke_authority_projection(query.clone()).unwrap();
                let page = crate::agent_sdk::authority::AuthorityInventoryProjectionPage::decode(
                    &response,
                )
                .unwrap();
                page.validate_shape().unwrap();
                assert_eq!(page.credential.query, query);
                assert_eq!(page.credential.head, projection.head);
                assert!(page.unchanged && page.entries.is_empty() && page.next.is_none());
                assert_eq!(owner.ordered_index_for_test().unwrap(), before + 2);
                assert!(owner.record.pending_projection.is_none());
                assert!(
                    owner
                        .host
                        .lock()
                        .unwrap()
                        .retained_positive_clean_acknowledgement(agent, work, authorization)
                        .unwrap()
                );
            }
            harness.stop();
        }

        #[test]
        fn native_admin_retained_dispatch_recovers_before_and_after_execution() {
            native_admin_retained_terminal_recovery(false);
        }

        #[test]
        fn native_admin_denial_terminal_recovery_allows_valid_successor() {
            native_admin_retained_terminal_recovery(true);
        }

        fn native_admin_retained_terminal_recovery(denied: bool) {
            use super::super::admin_dispatch::terminal::{
                NativeAuthorityAdminTerminalSigner, NativeAuthorityAdminTerminalStore,
                verify_certificate,
            };
            use super::super::admin_dispatch::{
                NativeAuthorityAdminJournalStore, RetainedAuthorityAdminDispatch,
            };
            use crate::agent_sdk::authority::{AuthorityAdminCall, AuthorityAdminOperation};
            struct TerminalStore(OperationTestJournal, u8);
            fn terminal_key(id: InvocationId, retired: bool) -> InvocationId {
                InvocationId(Hash::digest(b"admin-terminal-test", &[&id.0, &[u8::from(retired)]]).0)
            }
            impl NativeAuthorityAdminTerminalStore for TerminalStore {
                type Error = std::io::Error;
                fn load(
                    &mut self,
                    id: InvocationId,
                    retired: bool,
                ) -> Result<Option<Vec<u8>>, Self::Error> {
                    self.0.load(terminal_key(id, retired))
                }
                fn retain(
                    &mut self,
                    id: InvocationId,
                    retired: bool,
                    bytes: &[u8],
                ) -> Result<(), Self::Error> {
                    if (self.1 == 0 && !retired) || (self.1 == 2 && retired) {
                        self.1 += 1;
                        return Err(std::io::Error::other("terminal failure before publication"));
                    }
                    self.0.retain(terminal_key(id, retired), bytes)?;
                    if (self.1 == 1 && !retired) || (self.1 == 3 && retired) {
                        self.1 += 1;
                        return Err(std::io::Error::other("terminal failure after publication"));
                    }
                    Ok(())
                }
            }
            struct TerminalSigner(usize);
            impl NativeAuthorityAdminPreparationSigner for TerminalSigner {
                type Error = std::io::Error;
                fn public_key(&self) -> [u8; 32] {
                    SigningKey::from_bytes(&[RECEIPT_SEED; 32])
                        .verifying_key()
                        .to_bytes()
                }
                fn sign_admin_preparation(
                    &mut self,
                    bytes: &[u8],
                ) -> Result<[u8; 64], Self::Error> {
                    Ok(SigningKey::from_bytes(&[RECEIPT_SEED; 32])
                        .sign(bytes)
                        .to_bytes())
                }
            }
            impl NativeAuthorityAdminTerminalSigner for TerminalSigner {
                type Error = std::io::Error;
                fn public_key(&self) -> [u8; 32] {
                    SigningKey::from_bytes(&[RECEIPT_SEED; 32])
                        .verifying_key()
                        .to_bytes()
                }
                fn sign_admin_terminal(&mut self, bytes: &[u8]) -> Result<[u8; 64], Self::Error> {
                    self.0 += 1;
                    Ok(SigningKey::from_bytes(&[RECEIPT_SEED; 32])
                        .sign(bytes)
                        .to_bytes())
                }
            }
            struct AdminJournal(OperationTestJournal, u8);
            impl NativeAuthorityAdminJournalStore for AdminJournal {
                type Error = std::io::Error;
                fn load(&mut self, id: InvocationId) -> Result<Option<Vec<u8>>, Self::Error> {
                    self.0.load(id)
                }
                fn retain(&mut self, id: InvocationId, bytes: &[u8]) -> Result<(), Self::Error> {
                    if self.1 == 2 {
                        self.1 = 1;
                        return Err(std::io::Error::other("injected failure before publication"));
                    }
                    self.0.retain(id, bytes)?;
                    if core::mem::take(&mut self.1) == 1 {
                        return Err(std::io::Error::other("published before injected failure"));
                    }
                    Ok(())
                }
            }
            let mut harness = NativeProjectionOwnerHarness::with_fixture(
                "native-admin-retained",
                native_bundled_authority_fixture(),
            );
            let mut owner = harness.owner.take().unwrap();
            let target = owner.authority_target();
            let slot = owner
                .supervisor_invocation_material(owner.pins.agent, target.binding.issuer.actor)
                .unwrap()
                .observed_slot;
            let key = SigningKey::from_bytes(&[CREDENTIAL_SEED; 32]);
            let public = key.verifying_key().to_bytes();
            let mut call = AuthorityAdminCall {
                invocation: InvocationId::ZERO,
                authority: target,
                administrator: owner.pins.descriptor.identity.owner,
                credential: CredentialId::of_public_key(&public),
                request_sequence: NonZeroU64::new(1).unwrap(),
                credential_public_key: public,
                authenticated_node: owner.pins.node,
                observed_slot: 0,
                expected_generation: NonZeroU64::new(1).unwrap(),
                operation: AuthorityAdminOperation::SetSpaceRole {
                    principal: owner.pins.descriptor.identity.owner,
                    role: crate::agent_sdk::RoleId([0x53; 32]),
                    granted: !denied,
                },
                signature: [1; 64],
            };
            call.invocation = call.expected_invocation();
            call.signature = key.sign(&call.signing_bytes()).to_bytes();
            let mut journal = AdminJournal(OperationTestJournal(harness._directory.0.clone()), 2);
            let mut operations = OperationTestJournal(harness._directory.0.clone());
            let mut terminals =
                TerminalStore(OperationTestJournal(harness._directory.0.clone()), 0);
            let mut terminal_signer = TerminalSigner(0);
            let draft = call.clone();
            let mut wrong_node = draft.clone();
            wrong_node.authenticated_node = crate::agent_sdk::NodeId([0xff; 32]);
            wrong_node.invocation = wrong_node.expected_invocation();
            wrong_node.signature = key.sign(&wrong_node.signing_bytes()).to_bytes();
            assert!(
                owner
                    .prepare_authority_admin(&wrong_node, &mut terminal_signer)
                    .is_err()
            );
            assert!(!owner.management_admission_held().unwrap());
            let preparation = owner
                .prepare_authority_admin(&draft, &mut terminal_signer)
                .unwrap();
            call = preparation.call_to_sign(&draft).unwrap();
            assert_eq!(call.signature, [0; 64]);
            call.signature = key.sign(&call.signing_bytes()).to_bytes();
            assert!(preparation.matches_call(&call));
            let submission =
                NativeAuthorityAdminSubmission::new(call.clone(), preparation.clone()).unwrap();
            let submitted_bytes = submission.encode().unwrap();
            assert_eq!(
                NativeAuthorityAdminSubmission::decode(&submitted_bytes).unwrap(),
                submission
            );
            for end in [0, 3, submitted_bytes.len() - 1] {
                assert!(NativeAuthorityAdminSubmission::decode(&submitted_bytes[..end]).is_err());
            }
            let mut trailing_submission = submitted_bytes.clone();
            trailing_submission.push(0);
            assert!(NativeAuthorityAdminSubmission::decode(&trailing_submission).is_err());
            assert!(
                NativeAuthorityAdminSubmission::decode(&vec![
                    0;
                    NativeAuthorityAdminSubmission::MAX_ENCODED_BYTES
                        + 1
                ])
                .is_err()
            );
            assert_eq!(call.observed_slot, slot);
            let mut changed_intent = call.clone();
            changed_intent.expected_generation = NonZeroU64::new(99).unwrap();
            changed_intent.invocation = changed_intent.expected_invocation();
            changed_intent.signature = key.sign(&changed_intent.signing_bytes()).to_bytes();
            assert!(!preparation.matches_call(&changed_intent));
            let encoded_preparation = preparation.encode().unwrap();
            for end in [0, 3, encoded_preparation.len() - 1] {
                assert!(
                    NativeAuthorityAdminPreparation::decode(&encoded_preparation[..end]).is_err()
                );
            }
            let mut bad_proof = encoded_preparation.clone();
            *bad_proof.last_mut().unwrap() ^= 1;
            let bad_proof = NativeAuthorityAdminPreparation::decode(&bad_proof).unwrap();
            assert!(!bad_proof.matches_call(&call));
            assert!(NativeAuthorityAdminSubmission::new(call.clone(), bad_proof.clone()).is_err());
            assert!(
                owner
                    .retain_authority_admin(&call, &bad_proof, &mut journal)
                    .is_err()
            );
            assert!(!owner.management_admission_held().unwrap());
            harness
                .fixture
                .logical_slot
                .as_ref()
                .unwrap()
                .store(slot + 1, Ordering::Release);
            let before = owner.ordered_index_for_test().unwrap();
            assert!(
                owner
                    .retain_authority_admin(&call, &preparation, &mut journal)
                    .is_err()
            );
            assert!(owner.management_admission_held().unwrap());
            assert_eq!(owner.ordered_index_for_test().unwrap(), before);
            assert!(journal.load(call.invocation).unwrap().is_none());
            harness
                .fixture
                .logical_slot
                .as_ref()
                .unwrap()
                .store(slot + 1, Ordering::Release);
            assert!(
                owner
                    .retain_authority_admin(&call, &preparation, &mut journal)
                    .is_err()
            );
            assert_eq!(owner.ordered_index_for_test().unwrap(), before);
            let bytes = journal.load(call.invocation).unwrap().unwrap();
            let retained = RetainedAuthorityAdminDispatch::decode(&bytes).unwrap();
            assert_eq!(retained.encode().unwrap(), bytes);
            let mut legacy = bytes.clone();
            legacy[..4].copy_from_slice(b"NAD1");
            assert!(RetainedAuthorityAdminDispatch::decode(&legacy).is_err());
            assert_eq!(
                owner
                    .retain_authority_admin(&call, &preparation, &mut journal)
                    .unwrap(),
                retained
            );
            for end in [0, 3, bytes.len() - 1] {
                assert!(RetainedAuthorityAdminDispatch::decode(&bytes[..end]).is_err());
            }
            let mut trailing = bytes.clone();
            trailing.push(0);
            assert!(RetainedAuthorityAdminDispatch::decode(&trailing).is_err());
            let mut forged = retained.clone();
            forged.call.signature[0] ^= 1;
            assert!(forged.encode().is_err());
            assert!(owner.execute_authority_admin(&forged).is_err());
            let mut wrong_anchor = retained.clone();
            wrong_anchor.anchor.runtime = HostHash([0xf1; 32]);
            assert!(owner.execute_authority_admin(&wrong_anchor).is_err());
            // A structurally valid envelope still cannot replace admitted gas.
            let mut substituted = retained.clone();
            if let RuntimeWork::Invoke {
                invocation,
                authorization,
                observed_slot,
                ..
            } = &mut substituted.envelope
            {
                invocation.gas -= 1;
                **authorization = InvocationAuthorization::PublicPreflight(
                    crate::agent_sdk::PublicPreflight::for_work(invocation, *observed_slot),
                );
            }
            assert!(substituted.encode().is_ok());
            assert!(owner.execute_authority_admin(&substituted).is_err());
            assert_eq!(owner.ordered_index_for_test().unwrap(), before);
            for ids in [
                vec![call.invocation, call.invocation],
                vec![InvocationId([0xff; 32])],
            ] {
                assert!(
                    NativeAuthorityOperationStartupAdmission::load(&mut operations, target, &[])
                        .unwrap()
                        .include_pending_admin(&mut journal, &ids)
                        .is_err()
                );
            }
            let mut first_result = None;
            for restart in 0..5 {
                let pins = owner._pins_store.clone();
                let record = owner.record_store.clone();
                let issuer = owner.issuer.into_store();
                drop(owner._network_host);
                drop(owner.host);
                harness
                    .fixture
                    .logical_slot
                    .as_ref()
                    .unwrap()
                    .store(slot + 10 + restart, Ordering::Release);
                let admission =
                    NativeAuthorityOperationStartupAdmission::load(&mut operations, target, &[])
                        .unwrap()
                        .include_admin_with_terminals(
                            &mut journal,
                            &mut terminals,
                            &[call.invocation],
                        )
                        .unwrap();
                owner = CleanSystemAgentBootstrapOwner::open_or_bootstrap_with_operation_admission(
                    pins,
                    record,
                    issuer,
                    &mut CountingSigner::new(),
                    || panic!("admin recovery must not recreate bootstrap"),
                    harness._directory.host(),
                    harness._directory.lock(),
                    harness.fixture.plan.pins.space,
                    harness.fixture.plan.pins.node,
                    harness.fixture.trust.clone(),
                    harness.fixture.merge.clone(),
                    harness.fixture.finality.clone(),
                    harness.provider.clone(),
                    harness.network.clone(),
                    None,
                    Some(&admission),
                )
                .unwrap_or_else(|error| {
                    panic!("admin reopen {restart} (denied={denied}): {error:?}")
                });
                drop(admission);
                assert_eq!(
                    owner.ordered_index_for_test().unwrap(),
                    before + [0, 1, 1, 2, 2][restart as usize]
                );
                if restart < 2 {
                    let recovered = owner
                        .retain_authority_admin(&call, &preparation, &mut journal)
                        .unwrap();
                    assert_eq!(recovered, retained);
                    let result = owner.execute_authority_admin(&recovered).unwrap();
                    assert_eq!(result.is_none(), denied);
                    if let Some(result) = &result {
                        assert_eq!(result.call, call);
                        assert_eq!(result.generation.get(), 2);
                    }
                    if let Some(first) = &first_result {
                        assert_eq!(first, &result);
                    } else {
                        first_result = Some(result);
                    }
                }
                let finished =
                    owner.finish_authority_admin(&retained, &mut terminals, &mut terminal_signer);
                if restart < 4 {
                    assert!(finished.is_err());
                    assert!(owner.management_admission_held().unwrap());
                    assert_eq!(
                        owner.ordered_index_for_test().unwrap(),
                        before + if restart < 2 { 1 } else { 2 }
                    );
                } else {
                    assert_eq!(finished.unwrap(), first_result.clone().unwrap());
                    assert!(!owner.management_admission_held().unwrap());
                    assert_eq!(terminal_signer.0, 4);
                    assert_eq!(owner.ordered_index_for_test().unwrap(), before + 2);
                }
                if let Some(bytes) = terminals.load(call.invocation, false).unwrap() {
                    assert!(verify_certificate(&retained, &bytes, true).is_err());
                    assert!(
                        NativeAuthorityAdminCompletion::verify(&call, &preparation, &bytes)
                            .is_err()
                    );
                    let mut corrupt = bytes;
                    *corrupt.last_mut().unwrap() ^= 1;
                    assert!(verify_certificate(&retained, &corrupt, false).is_err());
                }
                assert_eq!(journal.load(call.invocation).unwrap(), Some(bytes.clone()));
            }
            let terminal_bytes = terminals.load(call.invocation, true).unwrap().unwrap();
            let completion =
                NativeAuthorityAdminCompletion::verify(&call, &preparation, &terminal_bytes)
                    .unwrap();
            assert_eq!(completion.result(), first_result.as_ref().unwrap().as_ref());
            assert_eq!(
                submission.verify_completion(&terminal_bytes).unwrap(),
                completion
            );
            assert_eq!(completion.result().is_none(), denied);
            let mut legacy_terminal = terminal_bytes.clone();
            legacy_terminal[..4].copy_from_slice(b"NAT1");
            assert!(submission.verify_completion(&legacy_terminal).is_err());
            // Even a valid host signature for the same call at a different
            // physical incarnation must not accept this terminal certificate.
            let mut other_preparation = encoded_preparation.clone();
            other_preparation[4 + crate::agent_sdk::RUNTIME_ABI_ID.as_bytes().len() + 32 + 8] ^= 1;
            let signature_start = other_preparation.len() - 64;
            let mut signing = b"vos/agent/native-admin-preparation/v1".to_vec();
            signing.extend_from_slice(&other_preparation[4..signature_start - 4]);
            other_preparation[signature_start..].copy_from_slice(
                &SigningKey::from_bytes(&[RECEIPT_SEED; 32])
                    .sign(&signing)
                    .to_bytes(),
            );
            let other_preparation =
                NativeAuthorityAdminPreparation::decode(&other_preparation).unwrap();
            assert!(other_preparation.matches_call(&call));
            assert!(
                NativeAuthorityAdminCompletion::verify(&call, &other_preparation, &terminal_bytes)
                    .is_err()
            );
            for end in [0, 3, terminal_bytes.len() - 1] {
                assert!(
                    NativeAuthorityAdminCompletion::verify(
                        &call,
                        &preparation,
                        &terminal_bytes[..end]
                    )
                    .is_err()
                );
            }
            let mut altered_terminal = terminal_bytes.clone();
            *altered_terminal.last_mut().unwrap() ^= 1;
            assert!(
                NativeAuthorityAdminCompletion::verify(&call, &preparation, &altered_terminal)
                    .is_err()
            );
            assert!(
                NativeAuthorityAdminCompletion::verify(
                    &changed_intent,
                    &preparation,
                    &terminal_bytes
                )
                .is_err()
            );
            assert!(
                NativeAuthorityAdminCompletion::verify(&call, &bad_proof, &terminal_bytes).is_err()
            );
            let mut successor = call.clone();
            successor.observed_slot = 0;
            successor.expected_generation = NonZeroU64::new(if denied { 1 } else { 2 }).unwrap();
            successor.request_sequence = successor.expected_generation;
            successor.operation = AuthorityAdminOperation::SetSpaceRole {
                principal: successor.administrator,
                role: crate::agent_sdk::RoleId([0x54; 32]),
                granted: true,
            };
            successor.invocation = successor.expected_invocation();
            successor.signature = key.sign(&successor.signing_bytes()).to_bytes();
            let successor_draft = successor.clone();
            let successor_preparation = owner
                .prepare_authority_admin(&successor_draft, &mut terminal_signer)
                .unwrap();
            successor = successor_preparation
                .call_to_sign(&successor_draft)
                .unwrap();
            successor.signature = key.sign(&successor.signing_bytes()).to_bytes();
            owner
                .retain_authority_admin(&successor, &successor_preparation, &mut journal)
                .unwrap();
            let mut controller = NativeAuthorityAdminController::new(target, journal, terminals);
            let mut ids = vec![call.invocation, successor.invocation];
            ids.sort_unstable();
            let pins = owner._pins_store.clone();
            let record = owner.record_store.clone();
            let issuer = owner.issuer.into_store();
            drop(owner._network_host);
            drop(owner.host);
            let admission = controller
                .startup_admission(
                    NativeAuthorityOperationStartupAdmission::load(&mut operations, target, &[])
                        .unwrap(),
                    &ids,
                )
                .unwrap();
            owner = CleanSystemAgentBootstrapOwner::open_or_bootstrap_with_operation_admission(
                pins,
                record,
                issuer,
                &mut CountingSigner::new(),
                || panic!("admin controller recovery must not recreate bootstrap"),
                harness._directory.host(),
                harness._directory.lock(),
                harness.fixture.plan.pins.space,
                harness.fixture.plan.pins.node,
                harness.fixture.trust.clone(),
                harness.fixture.merge.clone(),
                harness.fixture.finality.clone(),
                harness.provider.clone(),
                harness.network.clone(),
                None,
                Some(&admission),
            )
            .unwrap();
            drop(admission);
            assert!(owner.management_admission_held().unwrap());
            controller
                .recover(&mut owner, &ids, &mut terminal_signer)
                .unwrap();
            assert!(!owner.management_admission_held().unwrap());
            let successor_result = controller
                .coordinate_and_retire(&mut owner, &successor, &mut terminal_signer)
                .unwrap();
            assert!(successor_result.is_some());
            let committed = owner.ordered_index_for_test().unwrap();
            let signatures = terminal_signer.0;
            assert_eq!(
                controller
                    .coordinate_and_retire(&mut owner, &successor, &mut terminal_signer)
                    .unwrap(),
                successor_result
            );
            assert_eq!(
                controller
                    .coordinate_and_retire(&mut owner, &call, &mut terminal_signer)
                    .unwrap(),
                first_result.unwrap()
            );
            assert_eq!(owner.ordered_index_for_test().unwrap(), committed);
            assert_eq!(terminal_signer.0, signatures);
            assert!(!owner.management_admission_held().unwrap());
            struct NoLifecycleStores;
            impl crate::agent::local_lifecycle::LocalLifecycleStoreFactory for NoLifecycleStores {
                type Intent = IssuerMemoryStore;
                type Issuer = IssuerMemoryStore;
                type Error = ();
                fn discover(&mut self, _: SpaceId, _: usize) -> Result<Vec<AgentId>, ()> {
                    panic!("admin must not discover lifecycle stores")
                }
                fn open_existing(
                    &mut self,
                    _: SpaceId,
                    _: AgentId,
                ) -> Result<(Self::Intent, Self::Issuer), ()> {
                    panic!("admin must not reopen lifecycle stores")
                }
                fn open(
                    &mut self,
                    _: SpaceId,
                    _: AgentId,
                ) -> Result<(Self::Intent, Self::Issuer), ()> {
                    panic!("admin must not create lifecycle stores")
                }
            }
            let local = crate::agent::local_sdk_host::LocalAgentHost::create(
                harness._directory.0.join("admin-local-host"),
                target.space,
                harness.fixture.plan.pins.node,
                harness.fixture.trust.clone(),
            )
            .unwrap();
            let mut lifecycle = crate::agent::local_lifecycle::LocalLifecycleController::new(
                owner,
                local,
                NoLifecycleStores,
                CountingSigner::new(),
            )
            .unwrap()
            .with_admins(controller, terminal_signer)
            .unwrap();
            assert_eq!(lifecycle.administer(&successor).unwrap(), successor_result);
            assert_eq!(
                lifecycle
                    .submit_admin(&successor, &successor_preparation)
                    .unwrap()
                    .result(),
                successor_result.as_ref()
            );
            assert!(lifecycle.submit_admin(&successor, &preparation).is_err());
            assert_eq!(lifecycle.ordered_index_for_test().unwrap(), committed);
            let mut next_draft = successor.clone();
            next_draft.observed_slot = 0;
            next_draft.expected_generation =
                NonZeroU64::new(successor.expected_generation.get() + 1).unwrap();
            next_draft.request_sequence = next_draft.expected_generation;
            next_draft.operation = AuthorityAdminOperation::SetSpaceRole {
                principal: next_draft.administrator,
                role: crate::agent_sdk::RoleId([0x55; 32]),
                granted: true,
            };
            next_draft.invocation = next_draft.expected_invocation();
            next_draft.signature = key.sign(&next_draft.signing_bytes()).to_bytes();
            use crate::agent::local_lifecycle::{
                LOCAL_LIFECYCLE_QUEUE_CAPACITY, LocalLifecycleIngressError, LocalLifecycleQueue,
                NativeLocalLifecycle, PendingLocalLifecycle,
            };
            let next_preparation =
                NativeLocalLifecycle::prepare_admin(&mut lifecycle, &next_draft).unwrap();
            let mut next_call = next_preparation.call_to_sign(&next_draft).unwrap();
            next_call.signature = key.sign(&next_call.signing_bytes()).to_bytes();
            assert!(lifecycle.administer(&next_call).is_err());
            assert_eq!(lifecycle.ordered_index_for_test().unwrap(), committed);
            assert!(
                !NativeLocalLifecycle::retains_admin(&mut lifecycle, &next_call, &next_preparation)
                    .unwrap()
            );
            let queue = LocalLifecycleQueue::default();
            assert!(matches!(
                queue.prepare_admin(next_draft.clone()),
                Err(LocalLifecycleIngressError::Unavailable)
            ));
            queue.open().unwrap();
            let mut invalid_draft = next_draft.clone();
            invalid_draft.signature[0] ^= 1;
            assert!(matches!(
                queue.prepare_admin(invalid_draft),
                Err(LocalLifecycleIngressError::Invalid)
            ));
            assert!(matches!(
                queue.submit_admin(next_call.clone(), preparation.clone()),
                Err(LocalLifecycleIngressError::Invalid)
            ));
            assert!(queue.pop().unwrap().is_none());
            let prepared_reply = queue.prepare_admin(next_draft.clone()).unwrap();
            let Some(PendingLocalLifecycle::PrepareAdmin { draft, reply }) = queue.pop().unwrap()
            else {
                panic!("missing queued admin preparation");
            };
            assert_eq!(draft, next_draft);
            reply
                .try_send(NativeLocalLifecycle::prepare_admin(&mut lifecycle, &draft))
                .unwrap();
            assert_eq!(prepared_reply.recv().unwrap().unwrap(), next_preparation);
            // A disconnected client must not cancel accepted mutation work.
            drop(
                queue
                    .submit_admin(next_call.clone(), next_preparation.clone())
                    .unwrap(),
            );
            let Some(PendingLocalLifecycle::SubmitAdmin {
                call: queued_call,
                preparation: queued_preparation,
                reply,
            }) = queue.pop().unwrap()
            else {
                panic!("accepted admin submission was cancelled");
            };
            assert_eq!(queued_call, next_call);
            assert_eq!(queued_preparation, next_preparation);
            let next_result = NativeLocalLifecycle::submit_admin(
                &mut lifecycle,
                &queued_call,
                &queued_preparation,
            )
            .unwrap();
            assert!(reply.try_send(Ok(next_result.clone())).is_err());
            assert!(next_result.result().is_some());
            assert_eq!(
                NativeAuthorityAdminCompletion::verify(
                    &next_call,
                    &next_preparation,
                    next_result.exact_bytes()
                )
                .unwrap(),
                next_result
            );
            assert!(
                NativeAuthorityAdminCompletion::verify(
                    &successor,
                    &successor_preparation,
                    next_result.exact_bytes()
                )
                .is_err()
            );
            assert!(
                NativeLocalLifecycle::retains_admin(&mut lifecycle, &next_call, &next_preparation)
                    .unwrap()
            );
            assert_eq!(lifecycle.ordered_index_for_test().unwrap(), committed + 2);
            assert_eq!(
                lifecycle
                    .submit_admin(&next_call, &next_preparation)
                    .unwrap(),
                next_result
            );
            assert_eq!(lifecycle.ordered_index_for_test().unwrap(), committed + 2);
            let pending_preparation = queue.prepare_admin(next_draft.clone()).unwrap();
            let pending: Vec<_> = (1..LOCAL_LIFECYCLE_QUEUE_CAPACITY)
                .map(|_| {
                    queue
                        .submit_admin(next_call.clone(), next_preparation.clone())
                        .unwrap()
                })
                .collect();
            assert!(matches!(
                queue.prepare_admin(next_draft.clone()),
                Err(LocalLifecycleIngressError::Busy)
            ));
            assert!(matches!(
                queue.submit_admin(next_call.clone(), next_preparation.clone()),
                Err(LocalLifecycleIngressError::Busy)
            ));
            queue.close();
            assert!(matches!(
                pending_preparation.recv().unwrap(),
                Err(SharedAgentHostError::Unavailable)
            ));
            for receiver in pending {
                assert!(matches!(
                    receiver.recv().unwrap(),
                    Err(SharedAgentHostError::Unavailable)
                ));
            }
            assert!(queue.pop().unwrap().is_none());
            assert!(matches!(
                queue.prepare_admin(next_draft),
                Err(LocalLifecycleIngressError::Unavailable)
            ));
            assert!(matches!(
                queue.submit_admin(next_call, next_preparation),
                Err(LocalLifecycleIngressError::Unavailable)
            ));
            drop(lifecycle);
            harness.stop();
        }

        #[test]
        fn native_admin_bundled_authority_grants_and_revokes_with_bound_identity() {
            use crate::agent_sdk::RoleId;
            use crate::agent_sdk::authority::{
                AuthorityAdminCall, AuthorityAdminOperation, AuthorityAdminResult,
                AuthorityCredentialProjection, AuthorityIngressAuthentication,
            };
            use crate::value::Value;

            let mut harness = NativeProjectionOwnerHarness::with_fixture(
                "bundled-authority-admin",
                native_bundled_authority_fixture(),
            );
            let owner = harness.owner.as_mut().unwrap();
            let key = SigningKey::from_bytes(&[CREDENTIAL_SEED; 32]);
            let public = key.verifying_key().to_bytes();
            let credential = CredentialId::of_public_key(&public);
            let role = RoleId([0x51; 32]);
            let (node_key, _, _, node) = node_material();
            let projection = |owner: &mut CleanSystemAgentBootstrapOwner<
                BootstrapMemoryStore,
                BootstrapMemoryStore,
                IssuerMemoryStore,
            >,
                              nonce: u8| {
                let mut query = AuthorityProjectionQuery {
                    authority: owner.authority_target(),
                    credential,
                    nonce: Hash([nonce; 32]),
                    selector: AuthorityProjectionSelector::Credential,
                    recovery: None,
                    authentication: AuthorityIngressAuthentication::SshNodeAttestation {
                        credential_public_key: public,
                        node: NodeId(node.0),
                        request_binding: Hash([nonce; 32]),
                        signature: [1; 64],
                    },
                };
                let signature = node_key.sign(&query.signing_bytes()).to_bytes();
                query.authentication = AuthorityIngressAuthentication::SshNodeAttestation {
                    credential_public_key: public,
                    node: NodeId(node.0),
                    request_binding: Hash([nonce; 32]),
                    signature,
                };
                AuthorityCredentialProjection::decode(
                    &owner.invoke_authority_projection(query).unwrap(),
                )
                .unwrap()
            };
            let mut current = projection(owner, 0xe1);
            assert!(!current.space_roles.contains(&role));
            for (step, granted) in [(0u8, true), (1, false)] {
                let target = owner.authority_target();
                let mut material = owner
                    .supervisor_invocation_material(owner.pins.agent, target.binding.issuer.actor)
                    .unwrap();
                material.root_provenance = false;
                let identity =
                    crate::agent::supervisor_adapters::physical_material_identity(&material)
                        .unwrap();
                let mut call = AuthorityAdminCall {
                    invocation: InvocationId::ZERO,
                    authority: target,
                    administrator: current.principal,
                    credential,
                    request_sequence: NonZeroU64::new(current.admin_request_high_water + 1)
                        .unwrap(),
                    credential_public_key: public,
                    authenticated_node: owner.pins.node,
                    observed_slot: material.observed_slot,
                    expected_generation: current.head.administration_generation,
                    operation: AuthorityAdminOperation::SetSpaceRole {
                        principal: current.principal,
                        role,
                        granted,
                    },
                    signature: [1; 64],
                };
                call.invocation = call.expected_invocation();
                call.signature = key.sign(&call.signing_bytes()).to_bytes();
                call.verify_with(&RawCredentialVerifier).unwrap();
                let mut availability = vec![material.program, material.schema, material.policies];
                availability.extend(material.installation_data);
                availability.sort_unstable_by(|a, b| a.reference.cmp(&b.reference));
                let work = InvocationWork {
                    space: target.space,
                    agent: target.system_agent,
                    runtime_deployment: target.system_runtime_deployment,
                    invocation: call.invocation,
                    actor: target.binding.issuer.actor,
                    incarnation: material.actor.incarnation,
                    deployment: target.binding.issuer.deployment,
                    program: target.binding.issuer.program,
                    mode: MethodMode::Linear,
                    origin: InvocationOrigin {
                        principal: Some(call.administrator),
                        credential: Some(credential),
                        transport_node: Some(call.authenticated_node),
                        actor: None,
                        capability: None,
                    },
                    roles: InvocationRoleClaims::none(),
                    message: dynamic_message(
                        "administer",
                        "call",
                        Value::Bytes(call.encode().unwrap()),
                    ),
                    installation_data: material.actor.entry.installation_data,
                    availability,
                    gas: owner.invocation_gas,
                    recovery_only: false,
                };
                // This exercises the native trusted boundary, not HTTP ingress.
                // A signed message alone must not supply its own caller identity.
                let mut anonymous_call = call.clone();
                anonymous_call.operation = AuthorityAdminOperation::SetSpaceRole {
                    principal: current.principal,
                    role: RoleId([0x52; 32]),
                    granted: true,
                };
                anonymous_call.invocation = anonymous_call.expected_invocation();
                anonymous_call.signature = key.sign(&anonymous_call.signing_bytes()).to_bytes();
                anonymous_call.verify_with(&RawCredentialVerifier).unwrap();
                let mut anonymous = work.clone();
                anonymous.origin = InvocationOrigin::anonymous();
                anonymous.invocation = anonymous_call.invocation;
                anonymous.message = dynamic_message(
                    "administer",
                    "call",
                    Value::Bytes(anonymous_call.encode().unwrap()),
                );
                for (candidate, accepted) in [(anonymous, false), (work, true)] {
                    let authorization = InvocationAuthorization::PublicPreflight(
                        crate::agent_sdk::PublicPreflight::for_work(&candidate, call.observed_slot),
                    );
                    let result = owner
                        .supervisor_invoke_terminal(
                            identity,
                            candidate.clone(),
                            authorization.clone(),
                        )
                        .unwrap();
                    let RuntimeOutcome::Completed(Ok(reply)) = result else {
                        panic!("admin invocation failed: {result:?}");
                    };
                    let Some(Value::Bytes(bytes)) = Value::try_decode(&reply.reply) else {
                        panic!("admin reply is not bytes");
                    };
                    if accepted {
                        let result = AuthorityAdminResult::decode(&bytes).unwrap();
                        result.verify_with(&RawCredentialVerifier).unwrap();
                        assert_eq!(result.call, call);
                        assert_eq!(result.generation, call.next_generation().unwrap());
                    } else {
                        assert!(bytes.is_empty());
                    }
                    assert!(matches!(
                        owner
                            .supervisor_acknowledge(identity, candidate, authorization,)
                            .unwrap(),
                        RuntimeOutcome::Acknowledged(Ok(_))
                    ));
                }
                current = projection(owner, 0xe2 + step);
                assert!(!current.space_roles.contains(&RoleId([0x52; 32])));
                assert_eq!(current.space_roles.contains(&role), granted);
                assert_eq!(
                    current.admin_request_high_water,
                    call.request_sequence.get()
                );
                assert_eq!(
                    current.head.administration_generation,
                    call.next_generation().unwrap()
                );
            }
            harness.stop();
        }

