            impl CleanManagementIssuerStore for ReplyStoreFailure {
                type Error = MemoryError;
                fn load(&mut self) -> Result<Option<Vec<u8>>, MemoryError> {
                    self.inner.load()
                }
                fn commit(&mut self, bytes: &[u8]) -> Result<(), MemoryError> {
                    if self.after_write {
                        self.inner.commit(bytes)?;
                    }
                    Err(MemoryError)
                }
            }
