            let query = crate::agent::production_owner::AuthorityProjectionQueryAuthenticator::authenticate(
                &mut authenticator, target, AuthorityProjectionSelector::Actors {
                    agent: target.system_agent, after: None, limit: 8,
                },
            ).unwrap();
